1	import { execFile } from "node:child_process";
2	import { promisify } from "node:util";
3	import { db } from "./db";
4	import { ovh, ovhApi, ovhConfigured } from "./ovh";
5	import { hetznerApi, hetznerConfigured } from "./hetzner";
6	import { SANDBOX, sandboxIp, sandboxMac } from "./sandbox";
7	import { getSettingInt } from "./settings";
8	import { agentHasLiveDnatRule } from "./node-agent";
9	import type { NodeProvider } from "@prisma/client";
10	
11	const execFileP = promisify(execFile);
12	
13	/**
14	 * Is this address already the target of a live DNAT rule on ITS OWN node?
15	 * Some infrastructure (the shared-hosting node, VM 200) reaches its dedicated
16	 * IP entirely through a whole-IP DNAT rule to an internal address — it has no
17	 * OVH Virtual MAC at all, so the MAC-based check above cannot see it. A real
18	 * incident: this exact IP was one query away from being handed to a game
19	 * server because "no Virtual MAC bound" was mistaken for "free" — it was
20	 * actively carrying production hosting traffic via `iptables -t nat`. Treat
21	 * any address with a live DNAT target as claimed, unconditionally.
22	 *
23	 * Dispatches by node: the primary's own local iptables (unchanged), or the
24	 * owning node's agent for anyone else — this used to always check the LOCAL
25	 * host regardless of which node `address` actually belongs to, which for a
26	 * non-primary node's pool checks the wrong machine's kernel entirely and
27	 * could double-allocate an address that's actually already claimed there.
28	 */
29	async function hasLiveDnatRule(node: NodeRow, address: string): Promise<boolean> {
30	  if (!node.isPrimary) {
31	    try {
32	      return await agentHasLiveDnatRule(node, address);
33	    } catch {
34	      // Agent unreachable/not configured — same fail-open reasoning as the
35	      // local case below: a false "not claimed" is recoverable (the Virtual
36	      // MAC check and the existing DB row are the other guards), a sync that
37	      // silently no-ops for an entire node's pool forever is not.
38	      return false;
39	    }
40	  }
41	  try {
42	    const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"]);
43	    return stdout.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
44	  } catch {
45	    // iptables unreadable (permissions, not present, sandboxed test env) — fail
46	    // closed is wrong here (it would make every sync a no-op); fail to "not
47	    // claimed by this specific check" and rely on the Virtual MAC check plus
48	    // the existing DB row remaining authoritative for anything already tracked.
49	    return false;
50	  }
51	}
52	
53	/**
54	 * What OVH actually bills per additional/failover IPv4 in the pool, in cents.
55	 * Single source of truth for both the IP-pool page's "OVH cost" stat and the
56	 * admin Accounting dashboard's auto-pulled infrastructure expense line — before
57	 * this it existed only as a copy of the same number hardcoded on the IP page.
58	 */
59	export const OVH_IP_UNIT_COST_CENTS = 239;
60	
61	/** Hetzner's "additional IP" rate, confirmed live in the Robot panel 2026-09-15. */
62	export const HETZNER_IP_UNIT_COST_CENTS = 200;
63	
64	/**
65	 * Fallback monthly price for a dedicated IPv4. Defaults to 0 — a dedicated IP is
66	 * INCLUDED on every plan (its cost is folded into plan pricing, as the marketing
67	 * pages state). The admin `dedicated_ip_price_cents` setting is the source of
68	 * truth; use `dedicatedIpMonthlyCents()` in billing paths, not this constant.
69	 */
70	export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 0);
71	
72	/**
73	 * The monthly dedicated-IP surcharge actually charged, from the admin setting
74	 * (`dedicated_ip_price_cents`, default 0 = included). Single source of truth for
75	 * every order/renewal/display path so they can never disagree.
76	 *
77	 * NORMALISED to a non-negative whole number of cents, exactly as
78	 * `extraDiskPerGbCents` (lib/disk-expand.ts) already does for the other
79	 * admin-priced add-on. `getSettingInt` is a raw `Number()` of whatever string sits
80	 * in the `Setting` row, so it happily returns 2.5 or -500. This value is multiplied
81	 * by the term length straight into `chargeCents` (lib/order.ts orderQuote) and into
82	 * `renewalCharge`, and from there into `debitWallet`, `unit_amount` and an Invoice
83	 * row — every one of which is integer cents. A fractional setting produced a
84	 * fractional charge that failed at Stripe or Prisma AFTER the customer had agreed
85	 * to it; a negative one silently discounted the plan.
86	 */
87	export async function dedicatedIpMonthlyCents(): Promise<number> {
88	  const v = await getSettingInt("dedicated_ip_price_cents", DEDICATED_IP_PRICE_CENTS);
89	  return Math.max(0, Math.round(v));
90	}
91	/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
92	export const DEDICATED_IP_BUFFER = Number(process.env.DEDICATED_IP_BUFFER ?? 2);
93	
94	/** OVH failover gateway = the host's /24 gateway (…​.254). OVH-specific — every
95	 *  additional/failover IP on an OVH dedicated server shares this one convention. */
96	function ovhGatewayFor(nodePublicIp: string): string {
97	  const parts = nodePublicIp.split(".");
98	  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
99	}
100	
101	/** Back-compat wrapper for any caller still expecting the old single-node signature. */
102	export function ovhGateway(): string {
103	  return ovhGatewayFor(process.env.PUBLIC_IP ?? "51.79.162.96");
104	}
105	
106	type NodeRow = {
107	  id: string;
108	  name: string;
109	  provider: NodeProvider;
110	  publicIp: string;
111	  providerServerId: string | null;
112	  isPrimary: boolean;
113	  agentPort: number;
114	  agentTokenEnc: string | null;
115	};
116	
117	const NODE_ROW_SELECT = {
118	  id: true,
119	  name: true,
120	  provider: true,
121	  publicIp: true,
122	  providerServerId: true,
123	  isPrimary: true,
124	  agentPort: true,
125	  agentTokenEnc: true,
126	} as const;
127	
128	/** Resolve the Node a dedicated-IP operation should act against: the id passed
129	 *  in explicitly, else the primary node — same fallback shape as
130	 *  worker/index.ts's nodeFor(), so single-node callers need no changes at all. */
131	async function resolveNode(nodeId?: string): Promise<NodeRow | null> {
132	  if (nodeId) {
133	    return db.node.findUnique({ where: { id: nodeId }, select: NODE_ROW_SELECT });
134	  }
135	  return db.node.findFirst({ where: { isPrimary: true }, select: NODE_ROW_SELECT });
136	}
137	
138	/** Is the right provider API even configured for this node? Dispatches by
139	 *  provider so a Hetzner-hosted server never silently falls through to
140	 *  checking whether OVH happens to be configured (the real bug this fixes —
141	 *  worker/index.ts used to gate purely on ovhConfigured(), with no node
142	 *  awareness at all). */
143	export async function dedicatedIpProviderConfigured(nodeId?: string): Promise<boolean> {
144	  const node = await resolveNode(nodeId);
145	  if (!node) return false;
146	  return node.provider === "HETZNER" ? hetznerConfigured() : ovhConfigured();
147	}
148	
149	/**
150	 * Pull additional/failover IPv4 addresses routed to a node's server from its
151	 * provider and upsert them into the pool. The host's own primary IP is never
152	 * poolable. Defaults to the primary (OVH) node when no `nodeId` is given —
153	 * identical behavior to before this file supported more than one node.
154	 */
155	export async function syncDedicatedIpPool(nodeId?: string): Promise<{ imported: number; total: number }> {
156	  if (SANDBOX) return { imported: 0, total: 0 };
157	  const node = await resolveNode(nodeId);
158	  if (!node || !node.providerServerId) return { imported: 0, total: 0 };
159	
160	  if (node.provider === "HETZNER") return syncHetznerPool(node);
161	  return syncOvhPool(node);
162	}
163	
164	async function syncOvhPool(node: NodeRow): Promise<{ imported: number; total: number }> {
165	  if (!ovhConfigured()) return { imported: 0, total: 0 };
166	  const SERVER = node.providerServerId!;
167	  const primary = node.publicIp;
168	  const blocks: string[] = await ovhApi.ips();
169	  let imported = 0;
170	  for (const block of blocks) {
171	    if (block.includes(":")) continue; // IPv6 handled separately
172	    let info: any;
173	    try {
174	      info = await ovhApi.ipInfo(block);
175	    } catch {
176	      continue;
177	    }
178	    if (info?.routedTo?.serviceName !== SERVER) continue;
179	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
180	    // A /32 block is a single usable IP == the block minus the mask.
181	    const address = block.split("/")[0];
182	    if (address === primary) continue;
183	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
184	    if (!existing) {
185	      // An IP that already has a Virtual MAC bound to it on OVH's side is already
186	      // in active use by SOME VM — possibly one this app never created a Server
187	      // row for (e.g. internal infrastructure provisioned directly via the OVH
188	      // API, like the cold-email relay). A genuinely free IP has no bound MAC
189	      // yet. Importing it as FREE anyway let a real customer server collide with
190	      // an unrelated VM's network identity — never assign an IP that's already
191	      // claimed at the network layer, regardless of whether our DB knows about it.
192	      if (await findVirtualMacForIp(SERVER, address)) continue;
193	      if (await hasLiveDnatRule(node, address)) continue;
194	      // Every IP this function imports is, by construction, a spare address
195	      // OVH says is routed to us and not yet claimed at the network layer — the
196	      // pool customer orders draw from. Internal-use IPs (the cold-email relay,
197	      // an owner-operated site, the shared-hosting node) are rare, hand-provisioned
198	      // one-offs marked INTERNAL by an admin after the fact; this sync has no way
199	      // to tell them apart from a genuinely free customer IP and must not try —
200	      // it always imports as CUSTOMER (the schema default, stated here for clarity).
201	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, nodeId: node.id, status: "FREE", purpose: "CUSTOMER" } });
202	      imported++;
203	    }
204	  }
205	  const total = await db.dedicatedIp.count({ where: { nodeId: node.id } });
206	  return { imported, total };
207	}
208	
209	/**
210	 * Hetzner side of the sync. Hetzner's `/ip` listing already returns exactly
211	 * the single additional IPs on the account (no failover/additional type
212	 * distinction to filter like OVH's `/ip` does) — every entry not equal to the
213	 * node's own main `publicIp` is poolable.
214	 */
215	async function syncHetznerPool(node: NodeRow): Promise<{ imported: number; total: number }> {
216	  if (!hetznerConfigured()) return { imported: 0, total: 0 };
217	  let imported = 0;
218	  // The Robot API wraps each entry as `{ ip: { ip: "1.2.3.4", server_ip: ..., ... } }`,
219	  // not a flat `{ ip: "1.2.3.4" }` — confirmed live 2026-09-15, the first time this
220	  // ever ran against a real account (Hetzner credentials had never been configured
221	  // before). The old flat-shape read left `address` holding the nested object, which
222	  // Prisma's `where: { address }` rejects outright — the sync could never have
223	  // succeeded even once.
224	  const ips: Array<{ ip: { ip: string; server_ip: string } }> = await hetznerApi.ips().catch(() => []);
225	  for (const entry of ips) {
226	    const address = entry.ip?.ip;
227	    if (!address || address === node.publicIp) continue;
228	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
229	    if (existing) continue;
230	    if (await hasLiveDnatRule(node, address)) continue;
231	    await db.dedicatedIp.create({
232	      data: { address, ovhBlock: "", nodeId: node.id, status: "FREE", purpose: "CUSTOMER" },
233	    });
234	    imported++;
235	  }
236	  const total = await db.dedicatedIp.count({ where: { nodeId: node.id } });
237	  return { imported, total };
238	}
239	
240	/** Count of IPs actually available to hand to a customer — same eligibility as
241	 * allocateDedicatedIp's claim query; excludes admin-marked INTERNAL rows. */
242	export async function freeCount(): Promise<number> {
243	  return db.dedicatedIp.count({ where: { status: "FREE", purpose: "CUSTOMER" } });
244	}
245	
246	/**
247	 * The real, live monthly bill for the whole dedicated-IP pool, in cents —
248	 * every pooled IP (free or assigned) costs its PROVIDER's per-IP rate
249	 * regardless of whether a customer is using it. Consumed by the Accounting
250	 * dashboard as an automatic recurring INFRASTRUCTURE expense line so this
251	 * cost is never hand-typed and can never drift from what /admin/ips itself
252	 * shows. Priced per-provider (not a single flat OVH rate) since 2026-09-15,
253	 * the day the first real Hetzner IP was pooled at its own, cheaper rate.
254	 */
255	export async function dedicatedIpPoolMonthlyCostCents(): Promise<number> {
256	  const counts = await db.dedicatedIp.groupBy({
257	    by: ["nodeId"],
258	    _count: true,
259	  });
260	  if (counts.length === 0) return 0;
261	  const nodes = await db.node.findMany({
262	    where: { id: { in: counts.map((c) => c.nodeId).filter((id): id is string => !!id) } },
263	    select: { id: true, provider: true },
264	  });
265	  const providerById = new Map(nodes.map((n) => [n.id, n.provider]));
266	  return counts.reduce((sum, c) => {
267	    const provider = c.nodeId ? providerById.get(c.nodeId) : undefined;
268	    const rate = provider === "HETZNER" ? HETZNER_IP_UNIT_COST_CENTS : OVH_IP_UNIT_COST_CENTS;
269	    return sum + c._count * rate;
270	  }, 0);
271	}
272	
273	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
274	async function findVirtualMacForIp(server: string, address: string): Promise<string | null> {
275	  const macs: string[] = await ovh("GET", `/dedicated/server/${server}/virtualMac`).catch(() => []);
276	  for (const m of macs) {
277	    const ips: string[] = await ovh("GET", `/dedicated/server/${server}/virtualMac/${m}/virtualAddress`).catch(() => []);
278	    if (ips.includes(address)) return m;
279	  }
280	  return null;
281	}
282	
283	/**
284	 * Claim a free IP for a server and set it up so the VM can use it — an OVH
285	 * Virtual MAC for an OVH-node IP, or nothing extra for a Hetzner-node IP
286	 * (Hetzner additional IPs route straight to the server's real MAC, no
287	 * separate MAC object to create). Returns the address + a MAC (OVH only,
288	 * empty string for Hetzner) + gateway, or null if none available.
289	 *
290	 * `nodeId` should be the server's OWN node — pass it explicitly from a
291	 * caller that already resolved it (e.g. worker/index.ts's `nodeFor(server)`);
292	 * omitted, this falls back to the primary node, identical to this file's
293	 * pre-multi-node behavior.
294	 */
295	export async function allocateDedicatedIp(
296	  serverId: string,
297	  vmid: number,
298	  nodeId?: string,
299	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
300	  if (SANDBOX) {
301	    // Hand out a synthetic dedicated IP without any provider call or pool mutation.
302	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
303	  }
304	  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
305	  // server already holds a fully-allocated dedicated IP, return it instead of
306	  // claiming a second pool IP — re-claiming would leak an IP and P2002 on the
307	  // unique DedicatedIp.serverId. An OVH row also needs a bound Virtual MAC to
308	  // count as "done"; a Hetzner row is done once ASSIGNED (no MAC step).
309	  const mine = await db.dedicatedIp.findUnique({ where: { serverId }, include: { node: true } });
310	  if (mine && mine.status === "ASSIGNED" && (mine.node.provider === "HETZNER" || mine.virtualMac)) {
311	    return { address: mine.address, virtualMac: mine.virtualMac ?? "", gateway: await gatewayFor(mine.node, mine.address) };
312	  }
313	
314	  const node = await resolveNode(nodeId);
315	  if (!node) return null;
316	  if (!(await dedicatedIpProviderConfigured(node.id))) return null;
317	
318	  // Atomically claim a FREE ip belonging to THIS node's pool. Excluding
319	  // purpose: INTERNAL here is a second, independent guard (alongside the
320	  // sync-time checks above) against ever handing an admin-marked internal IP
321	  // to a customer server.
322	  const claim = await db.$transaction(async (tx) => {
323	    const ip = await tx.dedicatedIp.findFirst({
324	      where: { status: "FREE", purpose: "CUSTOMER", nodeId: node.id },
325	      orderBy: { createdAt: "asc" },
326	    });
327	    if (!ip) return null;
328	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
329	    return ip;
330	  });
331	  if (!claim) return null;
332	
333	  try {
334	    if (node.provider === "HETZNER") {
335	      // Hetzner DOES require a registered virtual MAC per single additional
336	      // IP (corrected 2026-09-29 — see this file's header comment for the
337	      // real incident: any other MAC on the guest triggers Hetzner's own
338	      // network-abuse filtering). Robot's endpoint is rate-limited to 10
339	      // PUT/DELETE calls per hour, so ALWAYS check for an existing MAC via
340	      // GET first and only PUT when nothing is assigned yet — this must
341	      // never "refresh" a MAC that's already registered.
342	      let hetznerMac = "";
343	      try {
344	        // GET 404s ("mac not found") when nothing is registered yet — that's
345	        // the ordinary first-allocation case, not a failure; only create then.
346	        try {
347	          const info = await hetznerApi.macInfo(claim.address);
348	          hetznerMac = info?.mac?.mac ?? "";
349	        } catch (e) {
350	          if (!/-> 404/.test(String((e as Error)?.message))) throw e;
351	        }
352	        if (!hetznerMac) {
353	          const created = await hetznerApi.createMac(claim.address);
354	          hetznerMac = created?.mac?.mac ?? "";
355	        }
356	      } catch (e) {
357	        console.error(`[dedicated-ip] Hetzner virtual MAC lookup/create failed for ${claim.address} — provisioning will fall back to no explicit MAC (Hetzner may filter this as abuse)`, e);
358	      }
359	      await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: hetznerMac || null } });
360	      return { address: claim.address, virtualMac: hetznerMac, gateway: await gatewayFor(node, claim.address) };
361	    }
362	    // OVH branch — unchanged mechanics, just keyed off this node's own service name.
363	    const SERVER = node.providerServerId!;
364	    let mac = await findVirtualMacForIp(SERVER, claim.address);
365	    if (!mac) {
366	      // Creation is asynchronous (returns a task) — kick it off then poll.
367	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
368	      for (let i = 0; i < 40 && !mac; i++) {
369	        await new Promise((r) => setTimeout(r, 3000));
370	        mac = await findVirtualMacForIp(SERVER, claim.address);
371	      }
372	    }
373	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
374	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
375	    return { address: claim.address, virtualMac: mac, gateway: ovhGatewayFor(node.publicIp) };
376	  } catch (e) {
377	    // Roll the claim back to FREE on failure
378	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
379	    throw e;
380	  }
381	}
382	
383	/**
384	 * The gateway a VM should use for this IP. OVH: the well-known "/24 -> .254"
385	 * convention, same for every additional IP on that node. Hetzner: NOT a
386	 * fixed formula — Hetzner assigns a distinct gateway per single additional
387	 * IP (confirmed against Hetzner's own docs this session: additional IP
388	 * SUBNETS route via the server's main IP with no separate gateway, but
389	 * single additional IPs each come with their own gateway address) — read it
390	 * from Hetzner's own `/ip/{ip}` response rather than guessing a formula.
391	 * NOTE: the exact response field name below (`gateway`) hasn't been verified
392	 * against a real Hetzner additional IP yet (none exist in the pool at the
393	 * time this was written) — confirm it the first time this path actually
394	 * runs, before trusting it for a real customer's network config.
395	 */
396	async function gatewayFor(node: NodeRow, address: string): Promise<string> {
397	  if (node.provider === "OVH") return ovhGatewayFor(node.publicIp);
398	  try {
399	    const info = await hetznerApi.ipInfo(address);
400	    if (info?.ip?.gateway) return info.ip.gateway as string;
401	  } catch {
402	    /* fall through */
403	  }
404	  return node.publicIp; // best-effort fallback; see doc comment above
405	}
406	
407	/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual
408	 *  MAC for an OVH-node IP). A Hetzner-node IP's registered MAC is
409	 *  DELIBERATELY left in place — it's registered per-IP, not per-customer, so
410	 *  the next allocation of this same address just finds it via `macInfo` and
411	 *  reuses it (allocateDedicatedIp already checks before creating). Hetzner
412	 *  rate-limits PUT/DELETE on this endpoint to 10/hour; there is no benefit
413	 *  to spending that budget tearing a MAC down just to recreate the same one
414	 *  again shortly after. */
415	export async function releaseDedicatedIp(serverId: string): Promise<void> {
416	  if (SANDBOX) return;
417	  const ip = await db.dedicatedIp.findUnique({ where: { serverId }, include: { node: true } });
418	  if (!ip) return;
419	  if (ip.node.provider === "OVH" && ovhConfigured() && ip.virtualMac && ip.node.providerServerId) {
420	    const SERVER = ip.node.providerServerId;
421	    try {
422	      // Remove the IP from the vMAC, then delete the vMAC.
423	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
424	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
425	    } catch {
426	      /* best-effort */
427	    }
428	  }
429	  await db.dedicatedIp.update({
430	    where: { id: ip.id },
431	    data: { status: "FREE", serverId: null, virtualMac: null },
432	  });
433	  // `Server.ipAddress` is UNIQUE and separate from this pool table — every
434	  // caller used to have to remember to clear it themselves, and one (the
435	  // admin "release IP" action) didn't, which left a FREE pool row while a
436	  // live server still held that exact address in `Server.ipAddress`. The next
437	  // server to claim the pool row then failed provisioning with a P2002 on
438	  // every retry, deterministically, since the failed-provision cleanup just
439	  // re-freed the same already-stuck row. Clearing it here — for every caller,
440	  // guarded to only touch the row that still holds THIS address, since the
441	  // column also holds ordinary NAT IPs for other servers — closes that class
442	  // of bug for good instead of relying on each call site to remember.
443	  await db.server.updateMany({
444	    where: { id: serverId, ipAddress: ip.address },
445	    data: { ipAddress: null, ipv6: null },
446	  });
447	}
448	
449	/** Set reverse DNS (PTR) for a dedicated IP — dispatches to the owning node's provider. */
450	export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
451	  const ip = await db.dedicatedIp.findUnique({ where: { address }, include: { node: true } });
452	  if (!ip) return;
453	  if (ip.node.provider === "HETZNER") {
454	    if (!hetznerConfigured()) return;
455	    await hetznerApi.setReverse(address, reverse);
456	  } else {
457	    if (!ovhConfigured()) return;
458	    await ovhApi.setReverse(`${address}/32`, address, reverse);
459	  }
460	  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
461	}
