52	/**
53	 * The real, iptables-backed NatHost for the PRIMARY's own chain — the only
54	 * implementation production used before multi-node. The decision logic it is
55	 * handed to lives in lib/nat-rules.ts and is tested against an in-memory fake;
56	 * see the H5 incident note at the top of that file.
57	 */
58	function iptablesHost(chain: string): NatHost {
59	  return {
60	    ensureChain: () => ensureChainLocal(chain),
61	    listChain: async () => {
62	      const { stdout } = await exec("iptables", ["-t", "nat", "-S", chain]);
63	      return stdout;
64	    },
65	    addRule: (r: NatRule) => iptables(["-t", "nat", "-A", chain, ...ruleSpec(r)]),
66	    deleteRule: (r: NatRule) => iptables(["-t", "nat", "-D", chain, ...ruleSpec(r)]),
67	  };
68	}
