155	    try {
156	      const result = await reconcileNatChain(natHostFor(node, node.natChain), node.natChain, intent);
157	      if (result.unparsed.length) {
158	        console.warn(
159	          `[nat] ${node.name}/${node.natChain} contains ${result.unparsed.length} rule(s) this engine did ` +
160	            `not write and will not touch: ${result.unparsed.slice(0, 5).join(" | ")}`
161	        );
162	      }
163	      console.log(
164	        `[nat] ${node.name}/${node.natChain} verified: ${result.verified} rule(s) present ` +
165	          `(+${result.added} / -${result.deleted})`
166	      );
167	      results.push(result);
168	    } catch (e: any) {
169	      // Collected, not thrown immediately — one node's failure (agent
170	      // unreachable, no token configured, a genuinely broken ruleset) must
171	      // never prevent every OTHER node's sync from being attempted.
172	      const msg = `${node.name}/${node.natChain}: ${String(e?.message ?? e)}`;
173	      console.error(`[nat] sync FAILED for ${msg}`);
174	      errors.push(msg);
175	    }
176	  }
177	
178	  if (errors.length) {
179	    throw new Error(`NAT sync failed for ${errors.length} node(s): ${errors.join(" | ")}`);
180	  }
181	  return results;
182	}
183	
184	/**
185	 * For callers that must not be re-queued by a sync failure (server DELETE runs
186	 * this after the row is gone, so a throw dies on "Server not found" on retry and
187	 * the sync is never re-attempted — H5's aggravating factor).
188	 *
189	 * It still never claims success: the failure is logged in full and returned, so
190	 * the caller can surface it. What it will not do is convert a networking problem
191	 * into a stuck job that hides it.
192	 */
193	export async function syncPortForwardsBestEffort(context: string): Promise<Error | null> {
194	  try {
195	    await syncPortForwards();
196	    return null;
197	  } catch (e: any) {
198	    console.error(`[nat] port-forward sync FAILED after ${context} — forwarding may be wrong: ${e?.message ?? e}`);
199	    return e instanceof Error ? e : new Error(String(e));
200	  }
201	}
