1	import { db } from "./db";
2	import type { Prisma } from "@prisma/client";
3	
4	/**
5	 * IPAM — private-IP and SSH-forward-port allocation.
6	 *
7	 * Node-aware: when a `nodeId` is supplied the pool is taken from that Node's
8	 * configured range (`subnetPrefix` / `ipStart` / `ipEnd` / `sshPortStart` /
9	 * `sshPortEnd`). Without a nodeId we fall back to the global env range, which is
10	 * the single-node behaviour this module has always had.
11	 *
12	 * Race safety: `Server.ipAddress` and `Server.sshPort` are UNIQUE columns, so a
13	 * concurrent double-provision must not hand out the same value twice. When the
14	 * caller passes the server it is allocating for, the "find free + claim" pair
15	 * runs inside a single transaction guarded by a Postgres advisory lock, with a
16	 * retry loop on unique-constraint conflicts. Callers that do not pass a server
17	 * id get a best-effort pick plus a short-lived in-process reservation (which
18	 * covers concurrent jobs inside one worker process, the common case).
19	 *
20	 * `allocateSandboxVmid` below shares this same lock + retry machinery for a
21	 * third UNIQUE column, `Server.vmid`, in NXEON_SANDBOX mode (see its own doc
22	 * comment for the incident that made that necessary).
23	 */
24	
25	const ENV_SUBNET_PREFIX = process.env.NXEON_SUBNET_PREFIX ?? "10.20.0.";
26	const IP_START = Number(process.env.NXEON_IP_START ?? 100);
27	const IP_END = Number(process.env.NXEON_IP_END ?? 250);
28	export const SSH_PORT_START = Number(process.env.NXEON_SSH_PORT_START ?? 20000);
29	export const SSH_PORT_END = Number(process.env.NXEON_SSH_PORT_END ?? 29999);
30	
31	/** Advisory-lock key that serialises IPAM allocation across processes. */
32	const IPAM_LOCK_KEY = 728_144_301;
33	/** How many times we re-pick after losing a unique-constraint race. */
34	const CLAIM_ATTEMPTS = 8;
35	/** How long an unclaimed hand-out is remembered in this process. */
36	const RESERVATION_TTL_MS = 10 * 60_000;
37	/**
38	 * Sandbox-only vmids live at 990001+ — comfortably clear of any real Proxmox
39	 * id (those start at 100) so a sandbox value can never collide with one if a
40	 * tree is ever pointed at a real cluster by mistake. See `allocateSandboxVmid`.
41	 */
42	const SANDBOX_VMID_BASE = 990_000;
43	
44	export type IpamRange = {
45	  nodeId: string | null;
46	  subnetPrefix: string;
47	  ipStart: number;
48	  ipEnd: number;
49	  sshPortStart: number;
50	  sshPortEnd: number;
51	  bridge: string | null;
52	  natChain: string | null;
53	};
54	
55	const GLOBAL_RANGE: IpamRange = {
56	  nodeId: null,
57	  subnetPrefix: ENV_SUBNET_PREFIX,
58	  ipStart: IP_START,
59	  ipEnd: IP_END,
60	  sshPortStart: SSH_PORT_START,
61	  sshPortEnd: SSH_PORT_END,
62	  bridge: process.env.NXEON_BRIDGE ?? null,
63	  natChain: process.env.NXEON_NAT_CHAIN ?? null,
64	};
65	
66	const num = (v: unknown, fallback: number) =>
67	  typeof v === "number" && Number.isFinite(v) ? v : fallback;
68	
69	/**
70	 * Resolve the pool a node allocates from. Unknown/empty node fields fall back to
71	 * the global env values so a half-configured Node row can never produce an
72	 * empty range.
73	 */
74	export async function ipamRange(nodeId?: string | null): Promise<IpamRange> {
75	  if (!nodeId) return { ...GLOBAL_RANGE };
76	  const node = await db.node.findUnique({
77	    where: { id: nodeId },
78	    select: {
79	      id: true,
80	      subnetPrefix: true,
81	      ipStart: true,
82	      ipEnd: true,
83	      sshPortStart: true,
84	      sshPortEnd: true,
85	      bridge: true,
86	      natChain: true,
87	    },
88	  });
89	  if (!node) return { ...GLOBAL_RANGE };
90	  const prefix = node.subnetPrefix?.trim() || GLOBAL_RANGE.subnetPrefix;
91	  return {
92	    nodeId: node.id,
93	    subnetPrefix: prefix.endsWith(".") ? prefix : `${prefix}.`,
94	    ipStart: num(node.ipStart, GLOBAL_RANGE.ipStart),
95	    ipEnd: num(node.ipEnd, GLOBAL_RANGE.ipEnd),
96	    sshPortStart: num(node.sshPortStart, GLOBAL_RANGE.sshPortStart),
97	    sshPortEnd: num(node.sshPortEnd, GLOBAL_RANGE.sshPortEnd),
98	    bridge: node.bridge ?? GLOBAL_RANGE.bridge,
99	    natChain: node.natChain ?? GLOBAL_RANGE.natChain,
100	  };
101	}
102	
103	// ---------- in-process reservations ----------
104	
105	const reservations = new Map<string, number>();
106	
107	function isReserved(key: string): boolean {
108	  const until = reservations.get(key);
109	  if (until === undefined) return false;
110	  if (until <= Date.now()) {
111	    reservations.delete(key);
112	    return false;
113	  }
114	  return true;
115	}
116	
117	function reserve(key: string): void {
118	  if (reservations.size > 5000) {
119	    const now = Date.now();
120	    for (const [k, until] of reservations) if (until <= now) reservations.delete(k);
121	  }
122	  reservations.set(key, Date.now() + RESERVATION_TTL_MS);
123	}
124	
125	function isUniqueConflict(e: any): boolean {
126	  return e?.code === "P2002";
127	}
128	
129	type Tx = Prisma.TransactionClient;
130	
131	/**
132	 * Serialise allocators across processes with a transaction-scoped advisory lock
133	 * (auto-released on commit/rollback). Support is probed once OUTSIDE a
134	 * transaction — a failing statement inside an open Postgres transaction would
135	 * abort it, so we never speculatively try it in the hot path.
136	 */
137	let advisoryLocks: boolean | null = null;
138	// Two workarounds baked in:
139	//  - the key is a literal, not a bound parameter: a bound JS number can reach
140	//    Postgres as `numeric` and fail to resolve the ...(bigint) overload;
141	//  - pg_advisory_xact_lock() returns `void`, which Prisma's $queryRaw cannot
142	//    deserialize, so it is wrapped in a subselect that yields an int column.
143	const LOCK_SQL = `SELECT 1 AS locked FROM (SELECT pg_advisory_xact_lock(${IPAM_LOCK_KEY})) _lock`;
144	
145	async function lockIpam(tx: Tx): Promise<void> {
146	  if (advisoryLocks === false) return;
147	  await tx.$queryRawUnsafe(LOCK_SQL);
148	}
149	
150	async function probeAdvisoryLocks(): Promise<void> {
151	  if (advisoryLocks !== null) return;
152	  try {
153	    // Take and immediately release it (xact locks drop at commit). Done once,
154	    // outside the hot path, because a failing statement inside an open
155	    // transaction would abort that transaction.
156	    await db.$transaction(async (tx) => {
157	      await tx.$queryRawUnsafe(LOCK_SQL);
158	    });
159	    advisoryLocks = true;
160	  } catch {
161	    // Not Postgres, or the role lacks permission: the unique-conflict retry
162	    // loop plus in-process reservations remain as the safety net.
163	    advisoryLocks = false;
164	  }
165	}
166	
167	// ---------- IP allocation ----------
168	
169	/**
170	 * Candidate IPs are all `<prefix><n>`, so only servers already sitting in the
171	 * same subnet prefix can conflict — servers on other nodes (different prefix)
172	 * are naturally excluded. We still read the column globally because
173	 * `Server.ipAddress` is globally UNIQUE: skipping a value that another node
174	 * happens to hold is what keeps the insert from blowing up.
175	 */
176	async function pickFreeIp(tx: Tx, range: IpamRange): Promise<string> {
177	  const rows = await tx.server.findMany({
178	    where: { ipAddress: { startsWith: range.subnetPrefix } },
179	    select: { ipAddress: true },
180	  });
181	  const used = new Set(rows.map((r) => r.ipAddress!).filter(Boolean));
182	  for (let i = range.ipStart; i <= range.ipEnd; i++) {
183	    const ip = `${range.subnetPrefix}${i}`;
184	    if (used.has(ip)) continue;
185	    if (isReserved(`ip:${ip}`)) continue;
186	    return ip;
187	  }
188	  throw new Error(
189	    range.nodeId
190	      ? `IP pool exhausted for node ${range.nodeId} (${range.subnetPrefix}${range.ipStart}-${range.ipEnd})`
191	      : "IP pool exhausted"
192	  );
193	}
194	
195	/**
196	 * Allocate a private IP.
197	 *
198	 * @param nodeId          allocate from this Node's configured subnet/range.
199	 * @param claimForServerId when given, the IP is written onto that Server row in
200	 *                         the same transaction, making the allocation atomic.
201	 */
202	export async function allocateIp(
203	  nodeId?: string | null,
204	  claimForServerId?: string | null
205	): Promise<string> {
206	  const range = await ipamRange(nodeId);
207	  await probeAdvisoryLocks();
208	
209	  if (!claimForServerId) {
210	    // No row to claim against: pick + reserve in-process so concurrent jobs in
211	    // this worker cannot be handed the same address.
212	    const ip = await db.$transaction(async (tx) => {
213	      await lockIpam(tx);
214	      return pickFreeIp(tx, range);
215	    });
216	    reserve(`ip:${ip}`);
217	    return ip;
218	  }
219	
220	  let lastErr: unknown;
221	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
222	    let ip = "";
223	    try {
224	      ip = await db.$transaction(async (tx) => {
225	        await lockIpam(tx);
226	        const candidate = await pickFreeIp(tx, range);
227	        await tx.server.update({
228	          where: { id: claimForServerId },
229	          data: { ipAddress: candidate },
230	        });
231	        return candidate;
232	      });
233	    } catch (e) {
234	      lastErr = e;
235	      if (isUniqueConflict(e)) {
236	        // Someone beat us to it between pick and claim — skip it and retry.
237	        continue;
238	      }
239	      throw e;
240	    }
241	    reserve(`ip:${ip}`);
242	    return ip;
243	  }
244	  throw new Error(
245	    `IP allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
246	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
247	  );
248	}
249	
250	// ---------- SSH forward-port allocation ----------
251	
252	/**
253	 * `Server.sshPort` and `PortForward.publicPort` are both globally UNIQUE, so the
254	 * taken-set is read globally even though the *range* we scan is per-node.
255	 * Node-awareness therefore comes from the range: give each node a disjoint
256	 * sshPortStart/sshPortEnd window and two nodes can never collide.
257	 */
258	async function pickFreePort(tx: Tx, range: IpamRange): Promise<number> {
259	  const [servers, forwards] = await Promise.all([
260	    tx.server.findMany({
261	      where: { sshPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
262	      select: { sshPort: true },
263	    }),
264	    tx.portForward.findMany({
265	      where: { publicPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
266	      select: { publicPort: true },
267	    }),
268	  ]);
269	  const used = new Set<number>([
270	    ...servers.map((s) => s.sshPort!).filter((p) => p != null),
271	    ...forwards.map((f) => f.publicPort),
272	  ]);
273	  for (let p = range.sshPortStart; p <= range.sshPortEnd; p++) {
274	    if (used.has(p)) continue;
275	    if (isReserved(`port:${p}`)) continue;
276	    return p;
277	  }
278	  throw new Error(
279	    range.nodeId
280	      ? `SSH port pool exhausted for node ${range.nodeId} (${range.sshPortStart}-${range.sshPortEnd})`
281	      : "SSH port pool exhausted"
282	  );
283	}
284	
285	/**
286	 * Allocate an SSH forward port.
287	 *
288	 * @param nodeId          allocate from this Node's configured port range.
289	 * @param claimForServerId when given, the port is written onto that Server row
290	 *                         in the same transaction, making it atomic.
291	 */
292	export async function allocateSshPort(
293	  nodeId?: string | null,
294	  claimForServerId?: string | null
295	): Promise<number> {
296	  const range = await ipamRange(nodeId);
297	  await probeAdvisoryLocks();
298	
299	  if (!claimForServerId) {
300	    const port = await db.$transaction(async (tx) => {
301	      await lockIpam(tx);
302	      return pickFreePort(tx, range);
303	    });
304	    reserve(`port:${port}`);
305	    return port;
306	  }
307	
308	  let lastErr: unknown;
309	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
310	    let port = 0;
311	    try {
312	      port = await db.$transaction(async (tx) => {
313	        await lockIpam(tx);
314	        const candidate = await pickFreePort(tx, range);
315	        await tx.server.update({
316	          where: { id: claimForServerId },
317	          data: { sshPort: candidate },
318	        });
319	        return candidate;
320	      });
321	    } catch (e) {
322	      lastErr = e;
323	      if (isUniqueConflict(e)) continue;
324	      throw e;
325	    }
326	    reserve(`port:${port}`);
327	    return port;
328	  }
329	  throw new Error(
330	    `SSH port allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
331	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
332	  );
333	}
334	
335	/**
336	 * Allocate a sandbox vmid and claim it onto `serverId` atomically.
337	 *
338	 * NXEON_SANDBOX has no real Proxmox to hand out ids, so this used to be
339	 * `990000 + (await db.server.count())` inline in worker/index.ts's `provision()`.
340	 * That is not a per-server sequence — `count()` is just the CURRENT number of
341	 * Server rows, and minting a vmid fills in a column on a row that already
342	 * exists (checkout inserts the PENDING Server row immediately; the PROVISION
343	 * job that assigns `vmid` runs later, often for several orders back-to-back
344	 * with no new Server row created in between). Two servers provisioned while
345	 * the total row count hasn't moved computed the exact same vmid, and the
346	 * second `prisma.server.update()` died on the `vmid` unique constraint —
347	 * "Provisioning failed" for a customer whose order was otherwise fine.
348	 *
349	 * Fixed the same way `allocateIp`/`allocateSshPort` above fix the identical
350	 * class of bug for `Server.ipAddress`/`Server.sshPort`: pick MAX(vmid)+1 and
351	 * claim it in one transaction under the shared advisory lock, so no second
352	 * caller can observe the same MAX before the first one's claim lands. Where
353	 * advisory locks aren't available (probed once, see `probeAdvisoryLocks`) the
354	 * unique-constraint retry loop is the fallback, same as the IP/port allocators.
355	 */
356	export async function allocateSandboxVmid(serverId: string): Promise<number> {
357	  await probeAdvisoryLocks();
358	
359	  let lastErr: unknown;
360	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
361	    try {
362	      return await db.$transaction(async (tx) => {
363	        await lockIpam(tx);
364	        const highest = await tx.server.aggregate({ _max: { vmid: true } });
365	        const candidate = Math.max(SANDBOX_VMID_BASE, highest._max.vmid ?? SANDBOX_VMID_BASE) + 1;
366	        await tx.server.update({ where: { id: serverId }, data: { vmid: candidate } });
367	        return candidate;
368	      });
369	    } catch (e) {
370	      lastErr = e;
371	      if (isUniqueConflict(e)) continue; // lost the race — re-read MAX and retry
372	      throw e;
373	    }
374	  }
375	  throw new Error(
376	    `Sandbox vmid allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
377	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
378	  );
379	}
380	
381	/**
382	 * Auto-forward a game's own port at provision time, from the SAME pool and
383	 * under the SAME advisory lock as SSH ports (they've always shared one range
384	 * — see pickFreePort, which already checks both Server.sshPort AND
385	 * PortForward.publicPort). Without this, a NAT (non-dedicated-IP) game
386	 * server's game port was reachable by nobody until the customer manually
387	 * added a forward from the dashboard — found live via a real customer whose
388	 * Minecraft server had zero forwards and no dedicated IP, so its game port
389	 * had no path from any public IP at all. Dedicated-IP servers need no
390	 * forward (their guest port IS the public port) — callers should only call
391	 * this for the NAT case.
392	 */
393	export async function allocateGameForward(
394	  nodeId: string | null | undefined,
395	  serverId: string,
396	  guestPort: number,
397	  protocol: "tcp" | "udp" = "tcp"
398	): Promise<number> {
399	  const range = await ipamRange(nodeId);
400	  await probeAdvisoryLocks();
401	
402	  let lastErr: unknown;
403	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
404	    let port = 0;
405	    try {
406	      port = await db.$transaction(async (tx) => {
407	        await lockIpam(tx);
408	        const candidate = await pickFreePort(tx, range);
409	        await tx.portForward.create({
410	          data: { serverId, publicPort: candidate, guestPort, protocol },
411	        });
412	        return candidate;
413	      });
414	    } catch (e) {
415	      lastErr = e;
416	      if (isUniqueConflict(e)) continue;
417	      throw e;
418	    }
419	    reserve(`port:${port}`);
420	    return port;
421	  }
422	  throw new Error(
423	    `Game port forward allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
424	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
425	  );
426	}
