428	// ---------- gateway ----------
429	
430	/**
431	 * Gateway for a NAT subnet. Backwards compatible: called with no argument it
432	 * returns the global gateway exactly as before. Pass a Node's `subnetPrefix`
433	 * (or use {@link gatewayIpForNode}) for multi-node correctness.
434	 */
435	export function gatewayIp(subnetPrefix?: string | null): string {
436	  const prefix = subnetPrefix?.trim() || ENV_SUBNET_PREFIX;
437	  return `${prefix.endsWith(".") ? prefix : `${prefix}.`}1`;
438	}
439	
440	/** Async node-aware variant of {@link gatewayIp}. */
441	export async function gatewayIpForNode(nodeId?: string | null): Promise<string> {
442	  const range = await ipamRange(nodeId);
443	  return gatewayIp(range.subnetPrefix);
444	}
