173	/**
174	 * Stream one backup file's raw bytes off a node's agent into `destPath`.
175	 * Deliberately bypasses agentRequest() (which JSON-parses every response) —
176	 * these are multi-GB vzdump archives, not small control-plane payloads, so
177	 * this goes straight to a Node stream pipeline instead of buffering the
178	 * whole file in memory.
179	 */
180	export async function agentDownloadBackupFile(node: AgentNode, relPath: string, destPath: string): Promise<void> {
181	  const token = nodeAgentToken(node);
182	  if (!token) {
183	    throw new NodeAgentError(`node "${node.name}" has no agent token configured — see /admin/nodes/${node.id}`, node.name);
184	  }
185	  const url = `https://${node.publicIp}:${node.agentPort}/v1/backup/file?path=${encodeURIComponent(relPath)}`;
186	  let res: Awaited<ReturnType<typeof undiciFetch>>;
187	  try {
188	    res = await undiciFetch(url, {
189	      method: "GET",
190	      headers: { Authorization: `Bearer ${token}` },
191	      dispatcher: insecureAgent,
192	      // Large archives over a public-internet link: a per-request timeout
193	      // would kill a legitimate multi-GB transfer partway through, so this
194	      // one call is unbounded — the caller (the collector's own per-node
195	      // budget) is what actually bounds a hung node.
196	      signal: undefined,
197	    });
198	  } catch (e: any) {
199	    throw new NodeAgentError(`could not reach node-agent on "${node.name}" for ${relPath}: ${e?.message ?? e}`, node.name);
200	  }
201	  if (!res.ok || !res.body) {
202	    const text = await res.text().catch(() => "");
203	    throw new NodeAgentError(`node-agent on "${node.name}" returned ${res.status} for ${relPath}: ${text.slice(0, 300)}`, node.name);
204	  }
205	  const { mkdir, rename, rm } = await import("node:fs/promises");
206	  const { createWriteStream } = await import("node:fs");
207	  const { Readable } = await import("node:stream");
208	  const { pipeline } = await import("node:stream/promises");
209	  const path = await import("node:path");
210	  await mkdir(path.dirname(destPath), { recursive: true });
211	  const tmp = `${destPath}.partial`;
212	  try {
213	    await pipeline(Readable.fromWeb(res.body as any), createWriteStream(tmp, { mode: 0o600 }));
214	  } catch (e) {
215	    await rm(tmp, { force: true });
216	    throw e;
217	  }
218	  await rename(tmp, destPath);
219	}
