265	/**
266	 * Detect the package manager on the far side and return the install prefix, or
267	 * throw if none is supported. Fixed strings only — no user input.
268	 */
269	export async function pkgInstallPrefix(conn: Client): Promise<string> {
270	  const pm = await exec(
271	    conn,
272	    "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
273	      "elif command -v dnf >/dev/null 2>&1; then echo dnf; " +
274	      "elif command -v yum >/dev/null 2>&1; then echo yum; else echo none; fi",
275	    QUICK_TIMEOUT_MS
276	  );
277	  const which = pm.stdout.trim();
278	  if (which === "apt") return "DEBIAN_FRONTEND=noninteractive apt-get install -y";
279	  if (which === "dnf") return "dnf install -y";
280	  if (which === "yum") return "yum install -y";
281	  throw new Error("No supported package manager (apt-get/dnf/yum) found on the server.");
282	}
