284	/**
285	 * A generated secret is about to be embedded in a SQL/PHP string literal or a
286	 * credentials file (delivered over STDIN). `generateStrongPassword` is
287	 * alphanumeric by design; assert it, because a stray quote, colon or backslash
288	 * would break out of that literal — `.pgpass` and MySQL defaults files are both
289	 * colon/backslash sensitive.
290	 *
291	 * Lifted out of worker/apps.ts so worker/databases.ts can reuse it rather than
292	 * grow a second copy that drifts.
293	 */
294	export function assertInertSecret(secret: string, what: string): void {
295	  assert(/^[A-Za-z0-9]{8,128}$/.test(secret), `Unexpected ${what} shape — refusing to use it.`);
296	}
297	
298	/** Trim remote output for a customer-facing error message. */
299	export function why(r: { stdout: string; stderr: string }): string {
300	  return (r.stderr || r.stdout).replace(/\s+/g, " ").trim().slice(0, 200);
301	}
302	
303	/** A URL-safe generated password (no shell metacharacters, no ambiguity). */
304	export function generateStrongPassword(len = 20): string {
305	  return randomBytes(len * 2)
306	    .toString("base64url")
307	    .replace(/[-_]/g, "")
308	    .slice(0, len);
309	}
