      }
    }
    try {
      const freeSlots = WORKER_CONCURRENCY - active.size;
      let claimedThisTick = 0;
      if (freeSlots > 0) {
        // Fetch more candidates than we have free slots for: some may be
        // filtered out below because their lock key (serverId, or job type
        // for the serverId-less job types) already has a job RUNNING, so a
        // plain `take: freeSlots` could under-claim even when plenty of
        // runnable work exists for OTHER servers.
        const candidates = await db.job.findMany({
          where: { status: "QUEUED" },
          orderBy: { createdAt: "asc" },
          take: CLAIM_BATCH_SIZE,
        });
        // Same-tick lock set: seeded with every lock key already RUNNING, and
        // grown as this tick claims more — see the long comment above `active`
        // for why this closes the "two QUEUED jobs for the same server (or
        // same serverId-less job type) in one batch" race that a DB-only
        // check could miss.
        const lockedKeys = new Set<string>();
        for (const a of active.values()) lockedKeys.add(a.lockKey);

        for (const candidate of candidates) {
          if (claimedThisTick >= freeSlots) break;
          const key = lockKeyFor(candidate);
          if (lockedKeys.has(key)) {
            // Another job with the same lock key is already RUNNING (or was
            // claimed earlier in this same tick) — leave it QUEUED. It will
            // be re-considered on a later tick once that job's slot frees, so
            // ordering relative to that job is preserved exactly.
            continue;
          }
          // Atomic claim: only the caller whose updateMany matches the still-
          // QUEUED row wins. If count===0 it was already taken (e.g. a retry
          // path, or in principle another worker) between our read above and
          // now — skip and move on to the next candidate rather than stalling
          // the whole tick on one lost race.
          const claim = await db.job.updateMany({
            where: { id: candidate.id, status: "QUEUED" },
            data: { status: "RUNNING", attempts: { increment: 1 } },
          });
          if (claim.count !== 1) continue;
          const claimed = await db.job.findUnique({ where: { id: candidate.id } });
          if (!claimed) continue;
          lockedKeys.add(key);
          claimedThisTick++;
          console.log(
            `[worker] job ${claimed.id} ${claimed.type} server=${claimed.serverId} claimed (${active.size + 1}/${WORKER_CONCURRENCY} slots busy)`
          );
          launch(claimed);
        }
      }
      if (claimedThisTick === 0) {
        // Nothing new started this tick — either the queue is empty, every
        // slot is busy, or every remaining candidate is blocked on a server
        // that already has a job running. Same POLL_MS cadence as before;
        // jobs run for minutes, so a few seconds of extra latency to notice a
        // freed slot is immaterial.
        await new Promise((r) => setTimeout(r, POLL_MS));
      }
    } catch (e) {
      console.error("[worker] loop error", e);
      await new Promise((r) => setTimeout(r, POLL_MS));
    }
  }
}

