#!/usr/bin/env node
"use strict";
const https = require("node:https");
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const { execFile } = require("node:child_process");
const PORT = Number(process.env.NXEON_AGENT_PORT || 8943);
const TOKEN = process.env.NXEON_AGENT_TOKEN || "";
const TLS_KEY = process.env.NXEON_AGENT_TLS_KEY || "/etc/nxeon/node-agent.key.pem";
const TLS_CERT = process.env.NXEON_AGENT_TLS_CERT || "/etc/nxeon/node-agent.cert.pem";
// Generous enough for any real cloud-init snippet (a few KB of YAML/bash);
// bounded so a malformed/malicious body can't exhaust memory.
const MAX_BODY_BYTES = 1024 * 1024;
const CMD_TIMEOUT_MS = 15_000;
if (!TOKEN || TOKEN.length < 20) {
  console.error("[node-agent] NXEON_AGENT_TOKEN is missing or suspiciously short — refusing to start. " +
    "onboard-node.sh generates a proper one; don't hand-edit /etc/nxeon/node-agent.env with a short value.");
  process.exit(1);
}
if (!Number.isInteger(PORT) || PORT < 1 || PORT > 65535) {
  console.error(`[node-agent] NXEON_AGENT_PORT=${process.env.NXEON_AGENT_PORT} is not a valid port — refusing to start.`);
