// ---- request body helpers ---------------------------------------------------
function readBody(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (c) => {
      size += c.length;
      if (size > MAX_BODY_BYTES) {
        reject(new Error("request body too large"));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

/** Parse a JSON body, or return undefined (never throws) so handlers can 400 cleanly. */
function parseJson(text) {
  try {
    return JSON.parse(text || "{}");
  } catch {
    return undefined;
  }
}

function sendJson(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) });
  res.end(body);
}

// ---- route handlers ---------------------------------------------------------

async function handleHealth(_req, res) {
  sendJson(res, 200, { ok: true, version: 1 });
}

async function handleEnsureChain(_req, res, rawBody) {
  const parsed = parseJson(rawBody);
  const chain = parsed && parsed.chain;
  if (!parsed || !CHAIN_RE.test(chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
  await ensureChain(chain);
  sendJson(res, 200, { ok: true });
}

async function handleListChain(_req, res, chain) {
  if (!CHAIN_RE.test(chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
  // Deliberately NOT swallowed on failure — reconcileNatChain always calls
  // ensure-chain immediately before this, so a real failure here (not "chain
  // missing", which can't happen given that ordering) is a genuine problem
  // the caller needs to see, exactly like the local iptablesHost() in
  // worker/network.ts never special-cases this either.
  const output = await iptables(["-t", "nat", "-S", chain]);
  sendJson(res, 200, { output });
}

async function handleAddRule(_req, res, rawBody) {
  const parsed = parseJson(rawBody);
  if (!parsed || !CHAIN_RE.test(parsed.chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
  if (!isValidRule(parsed.rule)) return sendJson(res, 400, { error: "invalid rule" });
  await iptables(["-t", "nat", "-A", parsed.chain, ...ruleSpec(parsed.rule)]);
  sendJson(res, 200, { ok: true });
}

async function handleDeleteRule(_req, res, rawBody) {
  const parsed = parseJson(rawBody);
  if (!parsed || !CHAIN_RE.test(parsed.chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
  if (!isValidRule(parsed.rule)) return sendJson(res, 400, { error: "invalid rule" });
  await iptables(["-t", "nat", "-D", parsed.chain, ...ruleSpec(parsed.rule)]);
  sendJson(res, 200, { ok: true });
}

/** Resolve `<storage>:snippets/<filename>` via pvesm and refuse anything that
 *  didn't land in a real snippets directory — defense in depth beyond the
 *  filename/storage allowlists above. */
async function resolveSnippetPath(storage, filename) {
  const target = await pvesmPath(`${storage}:snippets/${filename}`);
  if (!target.includes(`${path.sep}snippets${path.sep}`) && !target.endsWith(`${path.sep}snippets`)) {
    throw new Error("storage did not resolve to a snippets path");
  }
  return target;
}

async function handleWriteSnippet(_req, res, rawBody) {
  const parsed = parseJson(rawBody);
  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
  if (typeof parsed.content !== "string" || parsed.content.length > MAX_BODY_BYTES) {
    return sendJson(res, 400, { error: "invalid content" });
  }
  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, parsed.content, { mode: 0o600 });
  sendJson(res, 200, { ok: true });
}

async function handleDeleteSnippet(_req, res, rawBody) {
  const parsed = parseJson(rawBody);
  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
  fs.rmSync(target, { force: true });
  sendJson(res, 200, { ok: true });
}

}

async function handleDnatCheck(_req, res, address) {
  if (!IPV4_RE.test(address || "")) return sendJson(res, 400, { error: "invalid address" });
  const output = await iptables(["-t", "nat", "-S", "PREROUTING"]);
  const hasLiveDnatRule = output.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
  sendJson(res, 200, { hasLiveDnatRule });
}

/** Recursively-flat listing of the two backup subdirs this agent exposes —
 *  each entry's `path` is exactly what handleBackupFile expects back. Missing
 *  subdirs (e.g. a node with no vzdump guests yet) are not an error — an
 *  empty/partial manifest is itself the honest signal the primary's collector
 *  needs to raise, not something this endpoint should paper over. */
async function handleBackupManifest(_req, res) {
  const entries = [];
  for (const sub of ["platform", "status"]) {
    const dir = path.join(BACKUP_ROOT, sub);
    let names;
    try {
      names = fs.readdirSync(dir);
    } catch {
      continue; // subdir doesn't exist on this node yet — not an error
    }
    for (const name of names) {
      const rel = `${sub}/${name}`;
      if (!BACKUP_REL_RE.test(rel)) continue; // silently skip anything not on the allowlist
      let st;
      try {
        st = fs.statSync(path.join(dir, name));
      } catch {
        continue;
      }
      if (!st.isFile()) continue;
      entries.push({ path: rel, size: st.size, mtimeMs: st.mtimeMs });
    }
  }
  sendJson(res, 200, { entries });
}

/** Stream one backup file's raw bytes. `relPath` must match BACKUP_REL_RE
 *  (rules out traversal by construction — no `..`, no absolute path, no
 *  extension this platform doesn't itself produce) AND the resolved real
 *  path must land inside BACKUP_ROOT — same defense-in-depth shape as
 *  resolveSnippetPath() above, kept even though the regex alone should
 *  already be sufficient. */
async function handleBackupFile(_req, res, relPath) {
  if (!isStr(relPath, BACKUP_REL_RE)) return sendJson(res, 400, { error: "invalid path" });
  const full = path.join(BACKUP_ROOT, relPath);
  let real;
  try {
    real = fs.realpathSync(full);
  } catch {
    return sendJson(res, 404, { error: "not found" });
  }
  const rootReal = fs.realpathSync(BACKUP_ROOT);
  if (real !== rootReal && !real.startsWith(rootReal + path.sep)) {
    return sendJson(res, 400, { error: "path escapes backup root" });
  }
  let st;
  try {
    st = fs.statSync(real);
  } catch {
    return sendJson(res, 404, { error: "not found" });
  }
  if (!st.isFile()) return sendJson(res, 404, { error: "not found" });
  res.writeHead(200, {
    "Content-Type": "application/octet-stream",
    "Content-Length": st.size,
    "Content-Disposition": `attachment; filename="${path.basename(real)}"`,
  });
  fs.createReadStream(real).pipe(res);
}

// ---- router ------------------------------------------------------------------

async function route(req, res) {
  const url = new URL(req.url, `https://${req.headers.host || "localhost"}`);
  const { pathname, searchParams } = url;

  if (req.method === "GET" && pathname === "/v1/health") return handleHealth(req, res);

  if (req.method === "POST" && pathname === "/v1/nat/ensure-chain") return handleEnsureChain(req, res, await readBody(req));

  const chainMatch = /^\/v1\/nat\/chain\/([^/]+)$/.exec(pathname);
  if (req.method === "GET" && chainMatch) return handleListChain(req, res, decodeURIComponent(chainMatch[1]));

  if (req.method === "POST" && pathname === "/v1/nat/rule") return handleAddRule(req, res, await readBody(req));
  if (req.method === "DELETE" && pathname === "/v1/nat/rule") return handleDeleteRule(req, res, await readBody(req));

  if (req.method === "POST" && pathname === "/v1/snippet") return handleWriteSnippet(req, res, await readBody(req));
  if (req.method === "DELETE" && pathname === "/v1/snippet") return handleDeleteSnippet(req, res, await readBody(req));

  if (req.method === "GET" && pathname === "/v1/iptables/dnat-check") return handleDnatCheck(req, res, searchParams.get("address"));

  if (req.method === "GET" && pathname === "/v1/backup/manifest") return handleBackupManifest(req, res);
  if (req.method === "GET" && pathname === "/v1/backup/file") return handleBackupFile(req, res, searchParams.get("path"));

  sendJson(res, 404, { error: "not found" });
}

const server = https.createServer({ key: fs.readFileSync(TLS_KEY), cert: fs.readFileSync(TLS_CERT) }, (req, res) => {
  if (!checkAuth(req)) {
    sendJson(res, 401, { error: "unauthorized" });
    return;
  }
  route(req, res).catch((e) => {
    console.error("[node-agent] request error:", e && e.message ? e.message : e);
    try {
      sendJson(res, 500, { error: String((e && e.message) || e).slice(0, 300) });
    } catch {
      /* response already sent/closed */
    }
  });
});

server.listen(PORT, () => {
  console.log(`[node-agent] listening on :${PORT}`);
});

