/**
 * VM move — PURE planning logic. No DB, no Proxmox, no network: everything
 * here takes plain facts in and returns plain decisions out, so it is covered
 * end to end by test/vm-move-plan.test.ts without root, a hypervisor or a
 * second node. The side-effecting halves (lib/vm-move/preflight.ts gathers the
 * facts, worker/vm-move.ts acts on the decisions) stay as thin as possible.
 *
 * Covers: fleet-wide-unique target VMID choice (never a recycled id), target
 * capacity verdicts from REAL usage (not just committed plan RAM), candidate
 * classification + ranking for the primary offload, the phase state machine a
 * resumed job walks, the target VM config derivation, the move-safe cloud-init
 * vendor snippet, dataset-name validation shared with the node-agent, and the
 * OVH IP-move destination check (the campus/region guard).
 */
import { MOVE_PHASES, type MoveCandidate, type MoveCheckpoints, type MoveClass, type MovePhase, type NodeCapacityFacts, type PreflightCheck } from "./types";

// ---------------------------------------------------------------------------
// VMIDs
// ---------------------------------------------------------------------------

/** Templates live here on every node — never allocate into it (CLAUDE.md). */
export const TEMPLATE_VMID_MIN = 9000;
export const TEMPLATE_VMID_MAX = 9999;
/** Lowest id Proxmox accepts. */
export const VMID_MIN = 100;
/** Company infrastructure VMs sit at 8000+ (nxeon-mail) and 9010 (relay); the
 *  customer fleet is allocated below this so a move never lands on an
 *  infrastructure-looking id. */
export const CUSTOMER_VMID_MAX = 7999;

/**
 * Choose a BRAND-NEW vmid for the moved VM: strictly greater than every id the
 * fleet has ever seen in any of the sets handed in (live VMs on every node, the
 * DB's Server.vmid, archived servers, in-flight moves, backup archives on the
 * target). "Highest ever + 1" is what makes it impossible to recycle an id —
 * `pvesh get /cluster/nextid` returns the lowest FREE id, which on a
 * non-clustered fleet is almost always a destroyed VM's old number (the
 * 2026-09 "never reuse VMIDs" rule exists because recycled ids were found
 * live twice: a node offering an id a destroyed-but-still-in-DB server held,
 * and an id whose backup archives belonged to a previous tenant).
 *
 * The template band 9000–9999 is skipped (jumps to 10000), and ids above
 * CUSTOMER_VMID_MAX are ignored when computing the "highest customer id" so a
 * fleet whose only high id is nxeon-mail (8000) still allocates in the
 * customer band instead of jumping to 8001.
 */
export function pickMoveTargetVmid(sets: ReadonlyArray<Iterable<number>>): number {
  let highest = VMID_MIN - 1;
  const taken = new Set<number>();
  for (const set of sets) {
    for (const raw of set) {
      const id = Number(raw);
      if (!Number.isInteger(id) || id < VMID_MIN) continue;
      taken.add(id);
      if (id <= CUSTOMER_VMID_MAX && id > highest) highest = id;
    }
  }
  let candidate = highest + 1;
  for (let guard = 0; guard < 100_000; guard++, candidate++) {
    if (candidate >= TEMPLATE_VMID_MIN && candidate <= TEMPLATE_VMID_MAX) {
      candidate = TEMPLATE_VMID_MAX; // loop's ++ lands on 10000
      continue;
    }
    if (taken.has(candidate)) continue;
    return candidate;
  }
  throw new Error("pickMoveTargetVmid: could not find a free vmid");
}

// ---------------------------------------------------------------------------
// Datasets
// ---------------------------------------------------------------------------

/** A ZFS pool/dataset path as Proxmox's zfspool storage reports it in
 *  `pool` (e.g. `data`, `data/vms`, `rpool/data`). Shell-inert charset. */
export const ZFS_POOL_RE = /^[a-z][a-z0-9_-]{0,31}(\/[a-z][a-z0-9_-]{0,31}){0,3}$/;
/** The volume name Proxmox gives a VM disk. Only disk-0 is ever moved — a VM
 *  with more disks (block-storage volumes) is refused at preflight. */
export const VM_DISK_RE = /^vm-(\d{3,9})-disk-(\d{1,2})$/;
/** Snapshot names this engine creates: fixed prefix + the VmMove id (cuid). */
export const MOVE_SNAPSHOT_RE = /^nxmove[12]-[a-z0-9]{10,40}$/;

export function datasetFor(pool: string, vmid: number, disk = 0): string {
  if (!ZFS_POOL_RE.test(pool)) throw new Error(`refusing unexpected ZFS pool name ${JSON.stringify(pool)}`);
  if (!Number.isInteger(vmid) || vmid < VMID_MIN) throw new Error(`refusing vmid ${vmid}`);
  return `${pool}/vm-${vmid}-disk-${disk}`;
}

/** Validate a full dataset path `pool/vm-N-disk-M` and return its parts, or null. */
export function parseVmDataset(dataset: string): { pool: string; vmid: number; disk: number } | null {
  const slash = dataset.lastIndexOf("/");
  if (slash <= 0) return null;
  const pool = dataset.slice(0, slash);
  const name = dataset.slice(slash + 1);
  if (!ZFS_POOL_RE.test(pool)) return null;
  const m = VM_DISK_RE.exec(name);
  if (!m) return null;
  return { pool, vmid: Number(m[1]), disk: Number(m[2]) };
}

export function liveSnapshotName(moveId: string): string {
  return `nxmove1-${moveId}`;
}
export function incrementalSnapshotName(moveId: string): string {
  return `nxmove2-${moveId}`;
}

// ---------------------------------------------------------------------------
// Capacity
// ---------------------------------------------------------------------------

/** RAM a target host must still have REALLY available after the moved VM's
 *  full plan RAM is counted (the hypervisor, ZFS metadata, the agent and page
 *  cache all need room; a node with less than this is one burst from swap). */
export const TARGET_REAL_RAM_RESERVE_MB = Number(process.env.VM_MOVE_TARGET_RESERVE_MB ?? 4096);
/** Pool must keep this fraction free after the moved disk lands (ZFS
 *  performance collapses past ~80-85% full). */
export const TARGET_POOL_MIN_FREE_RATIO = 0.15;
/** Committed-RAM ceiling on the target after the move (same threshold the
 *  scheduler uses as "critical"). */
export const TARGET_COMMITTED_CRIT_PCT = 90;

export function capacityChecks(target: NodeCapacityFacts, planRamMB: number, planVcpu: number, usedBytes: number, diskSizeGB: number): PreflightCheck[] {
  const out: PreflightCheck[] = [];

  const availAfter = target.realAvailRamMB - planRamMB;
  out.push({
    id: "target-real-ram",
    ok: availAfter >= TARGET_REAL_RAM_RESERVE_MB,
    blocking: true,
    detail:
      `${target.name}: ${(target.realAvailRamMB / 1024).toFixed(1)} GB really available now, ` +
      `${(planRamMB / 1024).toFixed(1)} GB plan RAM moving in → ${(availAfter / 1024).toFixed(1)} GB left ` +
      `(needs ≥ ${(TARGET_REAL_RAM_RESERVE_MB / 1024).toFixed(1)} GB)`,
  });

  const committedAfterPct = target.capacityRamMB > 0 ? ((target.committedRamMB + planRamMB) / target.capacityRamMB) * 100 : 100;
  out.push({
    id: "target-committed-ram",
    ok: committedAfterPct < TARGET_COMMITTED_CRIT_PCT,
    blocking: true,
    detail: `${target.name}: committed ${(target.committedRamMB / 1024).toFixed(0)} → ${((target.committedRamMB + planRamMB) / 1024).toFixed(0)} GB of ${(target.capacityRamMB / 1024).toFixed(0)} GB (${committedAfterPct.toFixed(0)}%, limit ${TARGET_COMMITTED_CRIT_PCT}%)`,
  });

  // The zvol is sparse: what lands is roughly what the source really holds
  // (plus snapshot churn); the pool must still stay comfortably non-full.
  const freeAfter = target.poolFreeBytes - usedBytes;
  const freeAfterRatio = target.poolTotalBytes > 0 ? freeAfter / target.poolTotalBytes : 0;
  out.push({
    id: "target-pool-space",
    ok: freeAfter > 0 && freeAfterRatio >= TARGET_POOL_MIN_FREE_RATIO,
    blocking: true,
    detail: `${target.name}: pool ${(target.poolFreeBytes / 2 ** 30).toFixed(0)} GB free, disk really holds ${(usedBytes / 2 ** 30).toFixed(1)} GB (provisioned ${diskSizeGB} GB) → ${(freeAfter / 2 ** 30).toFixed(0)} GB free after (${(freeAfterRatio * 100).toFixed(0)}%, needs ≥ ${TARGET_POOL_MIN_FREE_RATIO * 100}%)`,
  });

  // vCPU is normally oversold; warn (not block) past 4x threads or when the
  // target is already busy.
  const vcpuAfter = target.committedVcpu + planVcpu;
  const ratio = target.cpuThreads > 0 ? vcpuAfter / target.cpuThreads : 99;
  out.push({
    id: "target-cpu",
    ok: ratio <= 4 && target.cpuLoad < 0.7,
    blocking: false,
    detail: `${target.name}: ${vcpuAfter} vCPU on ${target.cpuThreads} threads after (${ratio.toFixed(1)}x), load ${(target.cpuLoad * 100).toFixed(0)}% now`,
  });

  return out;
}

// ---------------------------------------------------------------------------
// Candidate classification + ranking
// ---------------------------------------------------------------------------

export type CandidateInput = {
  serverId: string;
  hostname: string;
  vmid: number | null;
  nodeId: string | null;
  status: string;
  planRamMB: number;
  planVcpu: number;
  diskGB: number;
  hasDedicatedIp: boolean;
  /** DedicatedIp.purpose === "INTERNAL" (owner-operated site, relay, hosting node). */
  internalIp: boolean;
  isFree: boolean;
  attachedVolumes: number;
  subdomain: string | null;
  forwardCount: number;
  gameFamily: string | null;
  realRssMB: number | null;
  /** Average kvm CPU% over the sample window when the caller measured it. */
  realCpuPct: number | null;
  /** Days until the term ends; null = never (free) / unknown. */
  daysToExpiry: number | null;
  autoRenew: boolean;
  /** Hostname/tag marks it as company infrastructure (nxeon-infra tag, no Server row…). */
  companyInfra: boolean;
};

export function classifyCandidate(c: CandidateInput): { klass: MoveClass; reasons: string[]; impact: string } {
  const reasons: string[] = [];
  if (c.companyInfra) reasons.push("company infrastructure (not a customer server)");
  if (c.internalIp) reasons.push("dedicated IP is marked INTERNAL");
  if (!c.vmid) reasons.push("no VM yet");
  if (c.attachedVolumes > 0) reasons.push(`${c.attachedVolumes} block-storage volume(s) attached — only single-disk VMs move`);
  if (!["RUNNING", "STOPPED"].includes(c.status)) reasons.push(`status ${c.status}`);
  if (reasons.length) return { klass: "C_MUST_STAY", reasons, impact: "not movable by this engine" };

  if (c.hasDedicatedIp) {
    return {
      klass: "A_DEDICATED_IP",
      reasons: ["public IP travels with the VM (OVH failover IP move + new Virtual MAC)"],
      impact: "no address change; a few minutes of downtime during cutover",
    };
  }
  const parts = ["public IP changes to the target node's IP; SSH/game ports keep their numbers"];
  if (c.subdomain) parts.push("Minecraft subdomain is repointed automatically (A+SRV)");
  if (c.forwardCount > 0) parts.push(`${c.forwardCount} port forward(s) recreated on the target`);
  return {
    klass: "B_NAT",
    reasons: parts,
    impact: c.subdomain ? "players using the subdomain see nothing; raw-IP users need the new address" : "customer must use the new IP (notice sent)",
  };
}

/**
 * Relief = how much real pressure leaves the source when this VM goes. Real RSS
 * (what the kvm process actually holds) dominates when known; plan RAM is the
 * fallback. CPU% adds to it — the primary is CPU-saturated as well as
 * RAM-starved. Risk = what can go wrong / how long it takes: disk size (dark
 * window), a dedicated IP (an extra reversible-but-external step), a subdomain
 * (DNS propagation), imminent expiry with auto-renew off (why move something
 * about to be deleted). Score = relief − risk/2 so a big idle NAT VM outranks a
 * small busy dedicated one, with class A ties broken toward dedicated-IP
 * servers (zero customer-visible change).
 */
export function scoreCandidate(c: CandidateInput, klass: MoveClass): { relief: number; risk: number; score: number } {
  const ramMB = c.realRssMB ?? c.planRamMB;
  const relief = Math.min(100, (ramMB / 8192) * 70 + Math.min(30, (c.realCpuPct ?? 0) / 4));
  let risk = Math.min(40, (c.diskGB / 100) * 40);
  if (klass === "A_DEDICATED_IP") risk += 10;
  if (c.subdomain) risk += 10;
  if (c.forwardCount > 2) risk += 5;
  if (c.daysToExpiry !== null && c.daysToExpiry <= 7 && !c.autoRenew) risk += 25;
  if (klass === "C_MUST_STAY") risk = 100;
  const bonus = klass === "A_DEDICATED_IP" ? 5 : 0;
  const score = klass === "C_MUST_STAY" ? -1 : Math.round(relief - risk / 2 + bonus);
  return { relief: Math.round(relief), risk: Math.round(risk), score };
}

export function rankMoveCandidates(inputs: readonly CandidateInput[]): MoveCandidate[] {
  const out: MoveCandidate[] = inputs.map((c) => {
    const { klass, reasons, impact } = classifyCandidate(c);
    const { relief, risk, score } = scoreCandidate(c, klass);
    return {
      serverId: c.serverId,
      hostname: c.hostname,
      vmid: c.vmid,
      nodeId: c.nodeId,
      klass,
      reasons,
      planRamMB: c.planRamMB,
      planVcpu: c.planVcpu,
      diskGB: c.diskGB,
      realRssMB: c.realRssMB,
      relief,
      risk,
      impact,
      score,
    };
  });
  // Movable first (by score desc), then must-stay; stable by hostname.
  return out.sort((a, b) => {
    const am = a.klass === "C_MUST_STAY" ? 1 : 0;
    const bm = b.klass === "C_MUST_STAY" ? 1 : 0;
    if (am !== bm) return am - bm;
    if (b.score !== a.score) return b.score - a.score;
    return a.hostname.localeCompare(b.hostname);
  });
}

// ---------------------------------------------------------------------------
// Phase state machine
// ---------------------------------------------------------------------------

/** Is phase `p` already complete according to the checkpoints? */
export function phaseComplete(p: MovePhase, cp: MoveCheckpoints, opts: { dedicated: boolean }): boolean {
  switch (p) {
    case "PREFLIGHT":
      return true; // a VmMove row with a plan exists by the time the worker runs
    case "SNAPSHOT_LIVE":
      return !!cp.liveSnapshotName;
    case "SEND_FULL":
      return !!cp.fullSentAt;
    case "STOP_SOURCE":
      return !!cp.sourceStoppedAt;
    case "SEND_INCREMENTAL":
      return !!cp.incrementalSentAt;
    case "CREATE_TARGET":
      return !!cp.targetVmCreated;
    case "MOVE_IP":
      return opts.dedicated ? !!cp.ipMovedAt : true;
    case "START_TARGET":
      return !!cp.targetVerified;
    case "COMMIT":
      return !!cp.committedAt;
    case "DONE":
      return !!cp.committedAt;
  }
}

/** The first phase a (resumed) run still has to execute. */
export function nextPhase(cp: MoveCheckpoints, opts: { dedicated: boolean }): MovePhase {
  for (const p of MOVE_PHASES) {
    if (p === "PREFLIGHT") continue;
    if (!phaseComplete(p, cp, opts)) return p;
  }
  return "DONE";
}

/** Phases that may be rolled back automatically (anything before COMMIT). Once
 *  COMMIT has run the DB points at the target; from there forward is the only
 *  safe direction and a human decides. */
export function rollbackAllowed(cp: MoveCheckpoints): boolean {
  return !cp.committedAt;
}

/** What rollback must undo, in order, given what the checkpoints say exists.
 *  Pure so the exact inventory is testable; the worker executes each step and
 *  records successes/failures on `checkpoints.rollback`. */
export type RollbackStep =
  | "MOVE_IP_BACK" // OVH: route the IP back to the source service + recreate the source Virtual MAC
  | "STOP_TARGET"
  | "DESTROY_TARGET_VM" // target VM config + its disks (the received dataset)
  | "DESTROY_TARGET_DATASET" // received dataset when no VM config references it yet
  | "DELETE_TARGET_SNIPPET"
  | "DELETE_SOURCE_INCREMENTAL_SNAPSHOT"
  | "START_SOURCE"
  | "RESTORE_DB_STATUS";
export function rollbackSteps(cp: MoveCheckpoints, opts: { dedicated: boolean }): RollbackStep[] {
  const steps: RollbackStep[] = [];
  if (opts.dedicated && cp.ipMovedAt) steps.push("MOVE_IP_BACK");
  if (cp.targetStartedAt) steps.push("STOP_TARGET");
  if (cp.targetVmCreated) steps.push("DESTROY_TARGET_VM");
  else if (cp.fullSentAt) steps.push("DESTROY_TARGET_DATASET");
  if (cp.targetSnippetWritten) steps.push("DELETE_TARGET_SNIPPET");
  if (cp.incrementalSnapshotName) steps.push("DELETE_SOURCE_INCREMENTAL_SNAPSHOT");
  if (cp.sourceStoppedAt) steps.push("START_SOURCE");
  steps.push("RESTORE_DB_STATUS");
  return steps;
}

// ---------------------------------------------------------------------------
// Target VM config derivation
// ---------------------------------------------------------------------------

/** Source config keys copied verbatim onto the target. Everything else is
 *  either regenerated (net0/ipconfig0/scsi0/ide2/cicustom/smbios1/vmgenid/
 *  meta/digest/snapshots) or must not travel (parent/snaptime/pending). */
export const CARRIED_CONFIG_KEYS = [
  "agent",
  "balloon",
  "bios",
  "boot",
  "ciuser",
  "cores",
  "cpu",
  "description",
  "hotplug",
  "kvm",
  "machine",
  "memory",
  "name",
  "nameserver",
  "numa",
  "onboot",
  "ostype",
  "protection",
  "scsihw",
  "searchdomain",
  "serial0",
  "sockets",
  "sshkeys",
  "tablet",
  "tags",
  "vga",
] as const;

/** Keys whose presence means the VM is NOT a plain single-disk cloud-init
 *  guest this engine knows how to move. */
export const REFUSED_CONFIG_KEY_RE = /^(scsi[1-9]\d*|virtio\d+|sata\d+|ide[013]|efidisk\d+|tpmstate\d+|unused\d+|hostpci\d+|usb\d+|parent|lock)$/;

export type SourceDiskInfo = { storage: string; volume: string; sizeGB: number; options: string };

/** Parse `scsi0: vmdata:vm-109-disk-0,discard=on,size=25G`. */
export function parseScsi0(value: string): SourceDiskInfo | null {
  const [volid, ...rest] = String(value).split(",");
  const [storage, volume] = volid.split(":");
  if (!storage || !volume || !VM_DISK_RE.test(volume)) return null;
  const sizeOpt = rest.find((o) => o.startsWith("size="));
  const size = sizeOpt ? sizeOpt.slice(5) : "";
  let sizeGB = 0;
  if (/^\d+G$/.test(size)) sizeGB = Number(size.slice(0, -1));
  else if (/^\d+T$/.test(size)) sizeGB = Number(size.slice(0, -1)) * 1024;
  else if (/^\d+M$/.test(size)) sizeGB = Math.ceil(Number(size.slice(0, -1)) / 1024);
  const options = rest.filter((o) => !o.startsWith("size=")).join(",");
  return { storage, volume, sizeGB, options };
}

/** Inspect a source config: which keys travel, which forbid the move, which
 *  snapshots exist (they are NOT carried — the customer would lose them). */
export function inspectSourceConfig(cfg: Record<string, unknown>): {
  carried: Record<string, string>;
  refusedKeys: string[];
  disk: SourceDiskInfo | null;
  hasCloudInitDrive: boolean;
  snapshotNames: string[];
} {
  const carried: Record<string, string> = {};
  const refusedKeys: string[] = [];
  let disk: SourceDiskInfo | null = null;
  let hasCloudInitDrive = false;
  for (const [k, v] of Object.entries(cfg)) {
    if (v === undefined || v === null) continue;
    if ((CARRIED_CONFIG_KEYS as readonly string[]).includes(k)) carried[k] = String(v);
    else if (k === "scsi0") disk = parseScsi0(String(v));
    else if (k === "ide2" && /cloudinit/.test(String(v))) hasCloudInitDrive = true;
    else if (REFUSED_CONFIG_KEY_RE.test(k)) refusedKeys.push(k);
  }
  const snapshotNames = Array.isArray((cfg as any).__snapshots) ? ((cfg as any).__snapshots as string[]) : [];
  return { carried, refusedKeys, disk, hasCloudInitDrive, snapshotNames };
}

export type TargetNetwork =
  | { kind: "DEDICATED"; address: string; gateway: string; virtualMac: string; bridge: string }
  | { kind: "NAT"; privateIp: string; gateway: string; mac: string | null; bridge: string };

/**
 * The config POSTed to create the target VM. The received dataset is attached
 * by volid (`<storage>:vm-<targetVmid>-disk-0` — Proxmox attaches an existing
 * volume when the name already carries the VM's own id); a fresh cloud-init
 * drive is created; `cicustom` points at the move-safe vendor snippet written
 * in the same phase; `onboot` is forced on (the source gets it forced OFF so a
 * source-node reboot can never resurrect a moved VM alongside its copy).
 */
export function buildTargetConfig(opts: {
  targetVmid: number;
  carried: Record<string, string>;
  disk: SourceDiskInfo;
  targetStorage: string;
  snippetStorage: string;
  network: TargetNetwork;
  cipassword: string | null;
}): Record<string, string | number> {
  const cfg: Record<string, string | number> = { ...opts.carried };
  cfg.vmid = opts.targetVmid;
  cfg.scsi0 = `${opts.targetStorage}:vm-${opts.targetVmid}-disk-0${opts.disk.options ? `,${opts.disk.options}` : ""}`;
  cfg.ide2 = `${opts.targetStorage}:cloudinit`;
  cfg.cicustom = `vendor=${opts.snippetStorage}:snippets/nxeon-${opts.targetVmid}.yaml`;
  cfg.onboot = 1;
  if (!cfg.scsihw) cfg.scsihw = "virtio-scsi-single";
  if (!cfg.boot) cfg.boot = "order=scsi0";
  if (opts.cipassword) cfg.cipassword = opts.cipassword;
  if (opts.network.kind === "DEDICATED") {
    cfg.net0 = `virtio=${opts.network.virtualMac},bridge=${opts.network.bridge}`;
    cfg.ipconfig0 = `ip=${opts.network.address}/32,gw=${opts.network.gateway}`;
  } else {
    cfg.net0 = opts.network.mac ? `virtio=${opts.network.mac},bridge=${opts.network.bridge}` : `virtio,bridge=${opts.network.bridge}`;
    cfg.ipconfig0 = `ip=${opts.network.privateIp}/24,gw=${opts.network.gateway}`;
  }
  return cfg;
}

/** Extract the MAC from `virtio=BC:24:11:..,bridge=vmbr1`. */
export function macFromNet0(net0: string | undefined): string | null {
  const m = /(?:^|,)virtio=([0-9A-Fa-f]{2}(?::[0-9A-Fa-f]{2}){5})/.exec(String(net0 ?? ""));
  return m ? m[1] : null;
}

/**
 * The vendor-data the moved VM boots with on its new node.
 *
 * WHY NOT the original per-VM snippet: Proxmox's NoCloud instance-id is a hash
 * of user-data + network-data, so the re-IP (or, for a dedicated IP, the new
 * gateway) makes cloud-init treat first boot on the target as a NEW INSTANCE
 * and re-run every per-instance module — including the original snippet's
 * `runcmd`, which would re-execute the game/app setup script against a server
 * that already has months of data on it, and `cc_ssh`, which by default
 * deletes and regenerates the host keys (every customer gets "REMOTE HOST
 * IDENTIFICATION HAS CHANGED"). This snippet keeps exactly the two things the
 * platform needs on every boot (guest agent, root SSH) and pins the host keys.
 */
export function moveSafeVendorSnippet(): string {
  return [
    "#cloud-config",
    "# Nxeon: post-move vendor data. Deliberately minimal — see lib/vm-move/plan.ts moveSafeVendorSnippet().",
    "ssh_deletekeys: false",
    "ssh_pwauth: true",
    "disable_root: false",
    "packages:",
    "  - qemu-guest-agent",
    "write_files:",
    "  - path: /etc/ssh/sshd_config.d/60-nxeon.conf",
    '    permissions: "0644"',
    "    content: |",
    "      PermitRootLogin yes",
    "      PasswordAuthentication yes",
    "runcmd:",
    "  - systemctl enable --now qemu-guest-agent",
    "  - systemctl restart ssh || systemctl restart sshd",
    "",
  ].join("\n");
}

// ---------------------------------------------------------------------------
// Dedicated IP move — destination guard
// ---------------------------------------------------------------------------

/** Shape of OVH `GET /ip/{ip}/move` (ip.Destinations). */
export type OvhMoveDestinations = { dedicatedServer?: Array<{ service: string; nexthop?: string[] }> };

/**
 * May this IP be moved to `targetService`? OVH only lists destinations in the
 * same campus (a Singapore failover IP lists the three SGP boxes and NOT
 * nxeon-bhs1 — confirmed live 2026-10-01). This is the authoritative
 * same-zone check; the Node.region equality check is the cheap pre-filter.
 * A wrong-zone move is simply impossible through this path rather than
 * "possible but unusable".
 */
export function ipMoveDestinationAllowed(dest: OvhMoveDestinations | null | undefined, targetService: string): boolean {
  const list = dest?.dedicatedServer ?? [];
  return list.some((d) => d?.service === targetService);
}

// ---------------------------------------------------------------------------
// Estimates
// ---------------------------------------------------------------------------

/** Assumed sustained inter-node rate for the stream (bytes/s). OVH SGP boxes
 *  share a 1 Gbit/s uplink; zstd + the source's load make ~60 MB/s a sober
 *  planning figure. Override via env for a measured value. */
export const ASSUMED_LINK_BYTES_PER_SEC = Number(process.env.VM_MOVE_LINK_BPS ?? 60 * 1024 * 1024);

export function estimateDurations(usedBytes: number, opts?: { linkBps?: number; incrementalRatio?: number }): { fullSendSec: number; downtimeSec: number } {
  const bps = opts?.linkBps ?? ASSUMED_LINK_BYTES_PER_SEC;
  const fullSendSec = Math.ceil(usedBytes / bps);
  // Dark window: shutdown (≤60s) + incremental (a few % of the disk changed
  // during the full send) + boot/agent/SSH verify (~60-90s).
  const incremental = usedBytes * (opts?.incrementalRatio ?? 0.03);
  const downtimeSec = 60 + Math.ceil(incremental / bps) + 90;
  return { fullSendSec, downtimeSec };
}

/** Relief the primary gets from a batch, for the plan document: Σ real RSS
 *  (or plan RAM) and Σ vCPU. */
export function batchRelief(cands: readonly MoveCandidate[]): { ramMB: number; vcpu: number } {
  return cands.reduce(
    (acc, c) => ({ ramMB: acc.ramMB + (c.realRssMB ?? c.planRamMB), vcpu: acc.vcpu + c.planVcpu }),
    { ramMB: 0, vcpu: 0 },
  );
}

toolu_01FdpmPMkn7PzHLm61nMjMDp.content:
/**
 * VM move — PURE planning logic. No DB, no Proxmox, no network: everything
 * here takes plain facts in and returns plain decisions out, so it is covered
 * end to end by test/vm-move-plan.test.ts without root, a hypervisor or a
 * second node. The side-effecting halves (lib/vm-move/preflight.ts gathers the
 * facts, worker/vm-move.ts acts on the decisions) stay as thin as possible.
 *
 * Covers: fleet-wide-unique target VMID choice (never a recycled id), target
 * capacity verdicts from REAL usage (not just committed plan RAM), candidate
 * classification + ranking for the primary offload, the phase state machine a
 * resumed job walks, the target VM config derivation, the move-safe cloud-init
 * vendor snippet, dataset-name validation shared with the node-agent, and the
 * OVH IP-move destination check (the campus/region guard).
 */
import { MOVE_PHASES, type MoveCandidate, type MoveCheckpoints, type MoveClass, type MovePhase, type NodeCapacityFacts, type PreflightCheck } from "./types";

// ---------------------------------------------------------------------------
// VMIDs
// ---------------------------------------------------------------------------

/** Templates live here on every node — never allocate into it (CLAUDE.md). */
export const TEMPLATE_VMID_MIN = 9000;
export const TEMPLATE_VMID_MAX = 9999;
/** Lowest id Proxmox accepts. */
export const VMID_MIN = 100;
/** Company infrastructure VMs sit at 8000+ (nxeon-mail) and 9010 (relay); the
 *  customer fleet is allocated below this so a move never lands on an
 *  infrastructure-looking id. */
export const CUSTOMER_VMID_MAX = 7999;

/**
 * Choose a BRAND-NEW vmid for the moved VM: strictly greater than every id the
 * fleet has ever seen in any of the sets handed in (live VMs on every node, the
 * DB's Server.vmid, archived servers, in-flight moves, backup archives on the
 * target). "Highest ever + 1" is what makes it impossible to recycle an id —
 * `pvesh get /cluster/nextid` returns the lowest FREE id, which on a
 * non-clustered fleet is almost always a destroyed VM's old number (the
 * 2026-09 "never reuse VMIDs" rule exists because recycled ids were found
 * live twice: a node offering an id a destroyed-but-still-in-DB server held,
 * and an id whose backup archives belonged to a previous tenant).
 *
 * The template band 9000–9999 is skipped (jumps to 10000), and ids above
 * CUSTOMER_VMID_MAX are ignored when computing the "highest customer id" so a
 * fleet whose only high id is nxeon-mail (8000) still allocates in the
 * customer band instead of jumping to 8001.
 */
export function pickMoveTargetVmid(sets: ReadonlyArray<Iterable<number>>): number {
  let highest = VMID_MIN - 1;
  const taken = new Set<number>();
  for (const set of sets) {
    for (const raw of set) {
      const id = Number(raw);
      if (!Number.isInteger(id) || id < VMID_MIN) continue;
      taken.add(id);
      if (id <= CUSTOMER_VMID_MAX && id > highest) highest = id;
    }
  }
  let candidate = highest + 1;
  for (let guard = 0; guard < 100_000; guard++, candidate++) {
    if (candidate >= TEMPLATE_VMID_MIN && candidate <= TEMPLATE_VMID_MAX) {
      candidate = TEMPLATE_VMID_MAX; // loop's ++ lands on 10000
      continue;
    }
    if (taken.has(candidate)) continue;
    return candidate;
  }
  throw new Error("pickMoveTargetVmid: could not find a free vmid");
}

// ---------------------------------------------------------------------------
// Datasets
// ---------------------------------------------------------------------------

/** A ZFS pool/dataset path as Proxmox's zfspool storage reports it in
 *  `pool` (e.g. `data`, `data/vms`, `rpool/data`). Shell-inert charset. */
export const ZFS_POOL_RE = /^[a-z][a-z0-9_-]{0,31}(\/[a-z][a-z0-9_-]{0,31}){0,3}$/;
/** The volume name Proxmox gives a VM disk. Only disk-0 is ever moved — a VM
 *  with more disks (block-storage volumes) is refused at preflight. */
export const VM_DISK_RE = /^vm-(\d{3,9})-disk-(\d{1,2})$/;
/** Snapshot names this engine creates: fixed prefix + the VmMove id (cuid). */
export const MOVE_SNAPSHOT_RE = /^nxmove[12]-[a-z0-9]{10,40}$/;

export function datasetFor(pool: string, vmid: number, disk = 0): string {
  if (!ZFS_POOL_RE.test(pool)) throw new Error(`refusing unexpected ZFS pool name ${JSON.stringify(pool)}`);
  if (!Number.isInteger(vmid) || vmid < VMID_MIN) throw new Error(`refusing vmid ${vmid}`);
  return `${pool}/vm-${vmid}-disk-${disk}`;
}

/** Validate a full dataset path `pool/vm-N-disk-M` and return its parts, or null. */
export function parseVmDataset(dataset: string): { pool: string; vmid: number; disk: number } | null {
  const slash = dataset.lastIndexOf("/");
  if (slash <= 0) return null;
  const pool = dataset.slice(0, slash);
  const name = dataset.slice(slash + 1);
  if (!ZFS_POOL_RE.test(pool)) return null;
  const m = VM_DISK_RE.exec(name);
  if (!m) return null;
  return { pool, vmid: Number(m[1]), disk: Number(m[2]) };
}

export function liveSnapshotName(moveId: string): string {
  return `nxmove1-${moveId}`;
}
export function incrementalSnapshotName(moveId: string): string {
  return `nxmove2-${moveId}`;
}

// ---------------------------------------------------------------------------
// Capacity
// ---------------------------------------------------------------------------

/** RAM a target host must still have REALLY available after the moved VM's
 *  full plan RAM is counted (the hypervisor, ZFS metadata, the agent and page
 *  cache all need room; a node with less than this is one burst from swap). */
export const TARGET_REAL_RAM_RESERVE_MB = Number(process.env.VM_MOVE_TARGET_RESERVE_MB ?? 4096);
/** Pool must keep this fraction free after the moved disk lands (ZFS
 *  performance collapses past ~80-85% full). */
export const TARGET_POOL_MIN_FREE_RATIO = 0.15;
/** Committed-RAM ceiling on the target after the move (same threshold the
 *  scheduler uses as "critical"). */
export const TARGET_COMMITTED_CRIT_PCT = 90;

export function capacityChecks(target: NodeCapacityFacts, planRamMB: number, planVcpu: number, usedBytes: number, diskSizeGB: number): PreflightCheck[] {
  const out: PreflightCheck[] = [];

  const availAfter = target.realAvailRamMB - planRamMB;
  out.push({
    id: "target-real-ram",
    ok: availAfter >= TARGET_REAL_RAM_RESERVE_MB,
    blocking: true,
    detail:
      `${target.name}: ${(target.realAvailRamMB / 1024).toFixed(1)} GB really available now, ` +
      `${(planRamMB / 1024).toFixed(1)} GB plan RAM moving in → ${(availAfter / 1024).toFixed(1)} GB left ` +
      `(needs ≥ ${(TARGET_REAL_RAM_RESERVE_MB / 1024).toFixed(1)} GB)`,
  });

  const committedAfterPct = target.capacityRamMB > 0 ? ((target.committedRamMB + planRamMB) / target.capacityRamMB) * 100 : 100;
  out.push({
    id: "target-committed-ram",
    ok: committedAfterPct < TARGET_COMMITTED_CRIT_PCT,
    blocking: true,
    detail: `${target.name}: committed ${(target.committedRamMB / 1024).toFixed(0)} → ${((target.committedRamMB + planRamMB) / 1024).toFixed(0)} GB of ${(target.capacityRamMB / 1024).toFixed(0)} GB (${committedAfterPct.toFixed(0)}%, limit ${TARGET_COMMITTED_CRIT_PCT}%)`,
  });

  // The zvol is sparse: what lands is roughly what the source really holds
  // (plus snapshot churn); the pool must still stay comfortably non-full.
  const freeAfter = target.poolFreeBytes - usedBytes;
  const freeAfterRatio = target.poolTotalBytes > 0 ? freeAfter / target.poolTotalBytes : 0;
  out.push({
    id: "target-pool-space",
    ok: freeAfter > 0 && freeAfterRatio >= TARGET_POOL_MIN_FREE_RATIO,
    blocking: true,
    detail: `${target.name}: pool ${(target.poolFreeBytes / 2 ** 30).toFixed(0)} GB free, disk really holds ${(usedBytes / 2 ** 30).toFixed(1)} GB (provisioned ${diskSizeGB} GB) → ${(freeAfter / 2 ** 30).toFixed(0)} GB free after (${(freeAfterRatio * 100).toFixed(0)}%, needs ≥ ${TARGET_POOL_MIN_FREE_RATIO * 100}%)`,
  });

  // vCPU is normally oversold; warn (not block) past 4x threads or when the
  // target is already busy.
  const vcpuAfter = target.committedVcpu + planVcpu;
  const ratio = target.cpuThreads > 0 ? vcpuAfter / target.cpuThreads : 99;
  out.push({
    id: "target-cpu",
    ok: ratio <= 4 && target.cpuLoad < 0.7,
    blocking: false,
    detail: `${target.name}: ${vcpuAfter} vCPU on ${target.cpuThreads} threads after (${ratio.toFixed(1)}x), load ${(target.cpuLoad * 100).toFixed(0)}% now`,
  });

  return out;
}

// ---------------------------------------------------------------------------
// Candidate classification + ranking
// ---------------------------------------------------------------------------

export type CandidateInput = {
  serverId: string;
  hostname: string;
  vmid: number | null;
  nodeId: string | null;
  status: string;
  planRamMB: number;
  planVcpu: number;
  diskGB: number;
  hasDedicatedIp: boolean;
  /** DedicatedIp.purpose === "INTERNAL" (owner-operated site, relay, hosting node). */
  internalIp: boolean;
  isFree: boolean;
  attachedVolumes: number;
  subdomain: string | null;
  forwardCount: number;
  gameFamily: string | null;
  realRssMB: number | null;
  /** Average kvm CPU% over the sample window when the caller measured it. */
  realCpuPct: number | null;
  /** Days until the term ends; null = never (free) / unknown. */
  daysToExpiry: number | null;
  autoRenew: boolean;
  /** Hostname/tag marks it as company infrastructure (nxeon-infra tag, no Server row…). */
  companyInfra: boolean;
};

export function classifyCandidate(c: CandidateInput): { klass: MoveClass; reasons: string[]; impact: string } {
  const reasons: string[] = [];
  if (c.companyInfra) reasons.push("company infrastructure (not a customer server)");
  if (c.internalIp) reasons.push("dedicated IP is marked INTERNAL");
  if (!c.vmid) reasons.push("no VM yet");
  if (c.attachedVolumes > 0) reasons.push(`${c.attachedVolumes} block-storage volume(s) attached — only single-disk VMs move`);
  if (!["RUNNING", "STOPPED"].includes(c.status)) reasons.push(`status ${c.status}`);
  if (reasons.length) return { klass: "C_MUST_STAY", reasons, impact: "not movable by this engine" };

  if (c.hasDedicatedIp) {
    return {
      klass: "A_DEDICATED_IP",
      reasons: ["public IP travels with the VM (OVH failover IP move + new Virtual MAC)"],
      impact: "no address change; a few minutes of downtime during cutover",
    };
  }
  const parts = ["public IP changes to the target node's IP; SSH/game ports keep their numbers"];
  if (c.subdomain) parts.push("Minecraft subdomain is repointed automatically (A+SRV)");
  if (c.forwardCount > 0) parts.push(`${c.forwardCount} port forward(s) recreated on the target`);
  return {
    klass: "B_NAT",
    reasons: parts,
    impact: c.subdomain ? "players using the subdomain see nothing; raw-IP users need the new address" : "customer must use the new IP (notice sent)",
  };
}

/**
 * Relief = how much real pressure leaves the source when this VM goes. Real RSS
 * (what the kvm process actually holds) dominates when known; plan RAM is the
 * fallback. CPU% adds to it — the primary is CPU-saturated as well as
 * RAM-starved. Risk = what can go wrong / how long it takes: disk size (dark
 * window), a dedicated IP (an extra reversible-but-external step), a subdomain
 * (DNS propagation), imminent expiry with auto-renew off (why move something
 * about to be deleted). Score = relief − risk/2 so a big idle NAT VM outranks a
 * small busy dedicated one, with class A ties broken toward dedicated-IP
 * servers (zero customer-visible change).
 */
export function scoreCandidate(c: CandidateInput, klass: MoveClass): { relief: number; risk: number; score: number } {
  const ramMB = c.realRssMB ?? c.planRamMB;
  const relief = Math.min(100, (ramMB / 8192) * 70 + Math.min(30, (c.realCpuPct ?? 0) / 4));
  let risk = Math.min(40, (c.diskGB / 100) * 40);
  if (klass === "A_DEDICATED_IP") risk += 10;
  if (c.subdomain) risk += 10;
  if (c.forwardCount > 2) risk += 5;
  if (c.daysToExpiry !== null && c.daysToExpiry <= 7 && !c.autoRenew) risk += 25;
  if (klass === "C_MUST_STAY") risk = 100;
  const bonus = klass === "A_DEDICATED_IP" ? 5 : 0;
  const score = klass === "C_MUST_STAY" ? -1 : Math.round(relief - risk / 2 + bonus);
  return { relief: Math.round(relief), risk: Math.round(risk), score };
}

export function rankMoveCandidates(inputs: readonly CandidateInput[]): MoveCandidate[] {
  const out: MoveCandidate[] = inputs.map((c) => {
    const { klass, reasons, impact } = classifyCandidate(c);
    const { relief, risk, score } = scoreCandidate(c, klass);
    return {
      serverId: c.serverId,
      hostname: c.hostname,
      vmid: c.vmid,
      nodeId: c.nodeId,
      klass,
      reasons,
      planRamMB: c.planRamMB,
      planVcpu: c.planVcpu,
      diskGB: c.diskGB,
      realRssMB: c.realRssMB,
      relief,
      risk,
      impact,
      score,
    };
  });
  // Movable first (by score desc), then must-stay; stable by hostname.
  return out.sort((a, b) => {
    const am = a.klass === "C_MUST_STAY" ? 1 : 0;
    const bm = b.klass === "C_MUST_STAY" ? 1 : 0;
    if (am !== bm) return am - bm;
    if (b.score !== a.score) return b.score - a.score;
    return a.hostname.localeCompare(b.hostname);
  });
}

// ---------------------------------------------------------------------------
// Phase state machine
// ---------------------------------------------------------------------------

/** Is phase `p` already complete according to the checkpoints? */
export function phaseComplete(p: MovePhase, cp: MoveCheckpoints, opts: { dedicated: boolean }): boolean {
  switch (p) {
    case "PREFLIGHT":
      return true; // a VmMove row with a plan exists by the time the worker runs
    case "SNAPSHOT_LIVE":
      return !!cp.liveSnapshotName;
    case "SEND_FULL":
      return !!cp.fullSentAt;
    case "STOP_SOURCE":
      return !!cp.sourceStoppedAt;
    case "SEND_INCREMENTAL":
      return !!cp.incrementalSentAt;
    case "CREATE_TARGET":
      return !!cp.targetVmCreated;
    case "MOVE_IP":
      return opts.dedicated ? !!cp.ipMovedAt : true;
    case "START_TARGET":
      return !!cp.targetVerified;
    case "COMMIT":
      return !!cp.committedAt;
    case "DONE":
      return !!cp.committedAt;
  }
}

/** The first phase a (resumed) run still has to execute. */
export function nextPhase(cp: MoveCheckpoints, opts: { dedicated: boolean }): MovePhase {
  for (const p of MOVE_PHASES) {
    if (p === "PREFLIGHT") continue;
    if (!phaseComplete(p, cp, opts)) return p;
  }
  return "DONE";
}

/** Phases that may be rolled back automatically (anything before COMMIT). Once
 *  COMMIT has run the DB points at the target; from there forward is the only
 *  safe direction and a human decides. */
export function rollbackAllowed(cp: MoveCheckpoints): boolean {
  return !cp.committedAt;
}

/** What rollback must undo, in order, given what the checkpoints say exists.
 *  Pure so the exact inventory is testable; the worker executes each step and
 *  records successes/failures on `checkpoints.rollback`. */
export type RollbackStep =
  | "MOVE_IP_BACK" // OVH: route the IP back to the source service + recreate the source Virtual MAC
  | "STOP_TARGET"
  | "DESTROY_TARGET_VM" // target VM config + its disks (the received dataset)
  | "DESTROY_TARGET_DATASET" // received dataset when no VM config references it yet
  | "DELETE_TARGET_SNIPPET"
  | "DELETE_SOURCE_INCREMENTAL_SNAPSHOT"
  | "START_SOURCE"
  | "RESTORE_DB_STATUS";
export function rollbackSteps(cp: MoveCheckpoints, opts: { dedicated: boolean }): RollbackStep[] {
  const steps: RollbackStep[] = [];
  if (opts.dedicated && cp.ipMovedAt) steps.push("MOVE_IP_BACK");
  if (cp.targetStartedAt) steps.push("STOP_TARGET");
  if (cp.targetVmCreated) steps.push("DESTROY_TARGET_VM");
  else if (cp.fullSentAt) steps.push("DESTROY_TARGET_DATASET");
  if (cp.targetSnippetWritten) steps.push("DELETE_TARGET_SNIPPET");
  if (cp.incrementalSnapshotName) steps.push("DELETE_SOURCE_INCREMENTAL_SNAPSHOT");
  if (cp.sourceStoppedAt) steps.push("START_SOURCE");
  steps.push("RESTORE_DB_STATUS");
  return steps;
}

// ---------------------------------------------------------------------------
// Target VM config derivation
// ---------------------------------------------------------------------------

/** Source config keys copied verbatim onto the target. Everything else is
 *  either regenerated (net0/ipconfig0/scsi0/ide2/cicustom/smbios1/vmgenid/
 *  meta/digest/snapshots) or must not travel (parent/snaptime/pending). */
export const CARRIED_CONFIG_KEYS = [
  "agent",
  "balloon",
  "bios",
  "boot",
  "ciuser",
  "cores",
  "cpu",
  "description",
  "hotplug",
  "kvm",
  "machine",
  "memory",
  "name",
  "nameserver",
  "numa",
  "onboot",
  "ostype",
  "protection",
  "scsihw",
  "searchdomain",
  "serial0",
  "sockets",
  "sshkeys",
  "tablet",
  "tags",
  "vga",
] as const;

/** Keys whose presence means the VM is NOT a plain single-disk cloud-init
 *  guest this engine knows how to move. */
export const REFUSED_CONFIG_KEY_RE = /^(scsi[1-9]\d*|virtio\d+|sata\d+|ide[013]|efidisk\d+|tpmstate\d+|unused\d+|hostpci\d+|usb\d+|parent|lock)$/;

export type SourceDiskInfo = { storage: string; volume: string; sizeGB: number; options: string };

/** Parse `scsi0: vmdata:vm-109-disk-0,discard=on,size=25G`. */
export function parseScsi0(value: string): SourceDiskInfo | null {
  const [volid, ...rest] = String(value).split(",");
  const [storage, volume] = volid.split(":");
  if (!storage || !volume || !VM_DISK_RE.test(volume)) return null;
  const sizeOpt = rest.find((o) => o.startsWith("size="));
  const size = sizeOpt ? sizeOpt.slice(5) : "";
  let sizeGB = 0;
  if (/^\d+G$/.test(size)) sizeGB = Number(size.slice(0, -1));
  else if (/^\d+T$/.test(size)) sizeGB = Number(size.slice(0, -1)) * 1024;
  else if (/^\d+M$/.test(size)) sizeGB = Math.ceil(Number(size.slice(0, -1)) / 1024);
  const options = rest.filter((o) => !o.startsWith("size=")).join(",");
  return { storage, volume, sizeGB, options };
}

/** Inspect a source config: which keys travel, which forbid the move, which
 *  snapshots exist (they are NOT carried — the customer would lose them). */
export function inspectSourceConfig(cfg: Record<string, unknown>): {
  carried: Record<string, string>;
  refusedKeys: string[];
  disk: SourceDiskInfo | null;
  hasCloudInitDrive: boolean;
  snapshotNames: string[];
} {
  const carried: Record<string, string> = {};
  const refusedKeys: string[] = [];
  let disk: SourceDiskInfo | null = null;
  let hasCloudInitDrive = false;
  for (const [k, v] of Object.entries(cfg)) {
    if (v === undefined || v === null) continue;
    if ((CARRIED_CONFIG_KEYS as readonly string[]).includes(k)) carried[k] = String(v);
    else if (k === "scsi0") disk = parseScsi0(String(v));
    else if (k === "ide2" && /cloudinit/.test(String(v))) hasCloudInitDrive = true;
    else if (REFUSED_CONFIG_KEY_RE.test(k)) refusedKeys.push(k);
  }
  const snapshotNames = Array.isArray((cfg as any).__snapshots) ? ((cfg as any).__snapshots as string[]) : [];
  return { carried, refusedKeys, disk, hasCloudInitDrive, snapshotNames };
}

export type TargetNetwork =
  | { kind: "DEDICATED"; address: string; gateway: string; virtualMac: string; bridge: string }
  | { kind: "NAT"; privateIp: string; gateway: string; mac: string | null; bridge: string };

/**
 * The config POSTed to create the target VM. The received dataset is attached
 * by volid (`<storage>:vm-<targetVmid>-disk-0` — Proxmox attaches an existing
 * volume when the name already carries the VM's own id); a fresh cloud-init
 * drive is created; `cicustom` points at the move-safe vendor snippet written
 * in the same phase; `onboot` is forced on (the source gets it forced OFF so a
 * source-node reboot can never resurrect a moved VM alongside its copy).
 */
export function buildTargetConfig(opts: {
  targetVmid: number;
  carried: Record<string, string>;
  disk: SourceDiskInfo;
  targetStorage: string;
  snippetStorage: string;
  network: TargetNetwork;
  cipassword: string | null;
}): Record<string, string | number> {
  const cfg: Record<string, string | number> = { ...opts.carried };
  cfg.vmid = opts.targetVmid;
  cfg.scsi0 = `${opts.targetStorage}:vm-${opts.targetVmid}-disk-0${opts.disk.options ? `,${opts.disk.options}` : ""}`;
  cfg.ide2 = `${opts.targetStorage}:cloudinit`;
  cfg.cicustom = `vendor=${opts.snippetStorage}:snippets/nxeon-${opts.targetVmid}.yaml`;
  cfg.onboot = 1;
  if (!cfg.scsihw) cfg.scsihw = "virtio-scsi-single";
  if (!cfg.boot) cfg.boot = "order=scsi0";
  if (opts.cipassword) cfg.cipassword = opts.cipassword;
  if (opts.network.kind === "DEDICATED") {
    cfg.net0 = `virtio=${opts.network.virtualMac},bridge=${opts.network.bridge}`;
    cfg.ipconfig0 = `ip=${opts.network.address}/32,gw=${opts.network.gateway}`;
  } else {
    cfg.net0 = opts.network.mac ? `virtio=${opts.network.mac},bridge=${opts.network.bridge}` : `virtio,bridge=${opts.network.bridge}`;
    cfg.ipconfig0 = `ip=${opts.network.privateIp}/24,gw=${opts.network.gateway}`;
  }
  return cfg;
}

/** Extract the MAC from `virtio=BC:24:11:..,bridge=vmbr1`. */
export function macFromNet0(net0: string | undefined): string | null {
  const m = /(?:^|,)virtio=([0-9A-Fa-f]{2}(?::[0-9A-Fa-f]{2}){5})/.exec(String(net0 ?? ""));
  return m ? m[1] : null;
}

/**
 * The vendor-data the moved VM boots with on its new node.
 *
 * WHY NOT the original per-VM snippet: Proxmox's NoCloud instance-id is a hash
 * of user-data + network-data, so the re-IP (or, for a dedicated IP, the new
 * gateway) makes cloud-init treat first boot on the target as a NEW INSTANCE
 * and re-run every per-instance module — including the original snippet's
 * `runcmd`, which would re-execute the game/app setup script against a server
 * that already has months of data on it, and `cc_ssh`, which by default
 * deletes and regenerates the host keys (every customer gets "REMOTE HOST
 * IDENTIFICATION HAS CHANGED"). This snippet keeps exactly the two things the
 * platform needs on every boot (guest agent, root SSH) and pins the host keys.
 */
export function moveSafeVendorSnippet(): string {
  return [
    "#cloud-config",
    "# Nxeon: post-move vendor data. Deliberately minimal — see lib/vm-move/plan.ts moveSafeVendorSnippet().",
    "ssh_deletekeys: false",
    "ssh_pwauth: true",
    "disable_root: false",
    "packages:",
    "  - qemu-guest-agent",
    "write_files:",
    "  - path: /etc/ssh/sshd_config.d/60-nxeon.conf",
    '    permissions: "0644"',
    "    content: |",
    "      PermitRootLogin yes",
    "      PasswordAuthentication yes",
    "runcmd:",
    "  - systemctl enable --now qemu-guest-agent",
    "  - systemctl restart ssh || systemctl restart sshd",
    "",
  ].join("\n");
}

// ---------------------------------------------------------------------------
// Dedicated IP move — destination guard
// ---------------------------------------------------------------------------

/** Shape of OVH `GET /ip/{ip}/move` (ip.Destinations). */
export type OvhMoveDestinations = { dedicatedServer?: Array<{ service: string; nexthop?: string[] }> };

/**
 * May this IP be moved to `targetService`? OVH only lists destinations in the
 * same campus (a Singapore failover IP lists the three SGP boxes and NOT
 * nxeon-bhs1 — confirmed live 2026-10-01). This is the authoritative
 * same-zone check; the Node.region equality check is the cheap pre-filter.
 * A wrong-zone move is simply impossible through this path rather than
 * "possible but unusable".
 */
export function ipMoveDestinationAllowed(dest: OvhMoveDestinations | null | undefined, targetService: string): boolean {
  const list = dest?.dedicatedServer ?? [];
  return list.some((d) => d?.service === targetService);
}

// ---------------------------------------------------------------------------
// Estimates
// ---------------------------------------------------------------------------

/** Assumed sustained inter-node rate for the stream (bytes/s). OVH SGP boxes
 *  share a 1 Gbit/s uplink; zstd + the source's load make ~60 MB/s a sober
 *  planning figure. Override via env for a measured value. */
export const ASSUMED_LINK_BYTES_PER_SEC = Number(process.env.VM_MOVE_LINK_BPS ?? 60 * 1024 * 1024);

export function estimateDurations(usedBytes: number, opts?: { linkBps?: number; incrementalRatio?: number }): { fullSendSec: number; downtimeSec: number } {
  const bps = opts?.linkBps ?? ASSUMED_LINK_BYTES_PER_SEC;
  const fullSendSec = Math.ceil(usedBytes / bps);
  // Dark window: shutdown (≤60s) + incremental (a few % of the disk changed
  // during the full send) + boot/agent/SSH verify (~60-90s).
  const incremental = usedBytes * (opts?.incrementalRatio ?? 0.03);
  const downtimeSec = 60 + Math.ceil(incremental / bps) + 90;
  return { fullSendSec, downtimeSec };
}

/** Relief the primary gets from a batch, for the plan document: Σ real RSS
 *  (or plan RAM) and Σ vCPU. */
export function batchRelief(cands: readonly MoveCandidate[]): { ramMB: number; vcpu: number } {
  return cands.reduce(
    (acc, c) => ({ ramMB: acc.ramMB + (c.realRssMB ?? c.planRamMB), vcpu: acc.vcpu + c.planVcpu }),
    { ramMB: 0, vcpu: 0 },
  );
}

