    res = await undiciFetch(url, { method: "GET", headers: { Authorization: `Bearer ${token}` }, dispatcher: insecureAgent, signal: undefined });
  } catch (e: any) {
    throw new NodeAgentError(`could not open zfs send from "${node.name}": ${e?.message ?? e}`, node.name);
