/**
 * The ZFS seam for VM moves — the same shape lib/nat-rules.ts's NatHost gives
 * NAT: every host-level ZFS operation a move needs, as an interface with three
 * implementations and one place that picks between them:
 *
 *   - localZfsHost()  — the primary itself (the worker runs there as root;
 *                       `zfs` is a local child process, argv arrays only).
 *   - agentZfsHost()  — any non-primary node, over its node-agent's
 *                       /v1/zfs/* endpoints (node-agent v2). The architecture's
 *                       standing rule: host-level work on another node goes
 *                       through its agent, not SSH.
 *   - sshZfsHost()    — TRANSITION FALLBACK ONLY (VM_MOVE_TRANSPORT=ssh): root
 *                       SSH from the primary to the node, for the window until
 *                       every node's agent has been updated to v2. Same argv
 *                       discipline, same dataset/snapshot allowlists. Remove
 *                       once every node reports agent version ≥ 2.
 *
 * Streams are zstd-compressed on the wire in every implementation so a
 * local→agent, agent→agent or ssh→local pairing all interoperate.
 */
import { spawn } from "node:child_process";
import { PassThrough, type Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import {
  agentZfsDataset,
  agentZfsDeleteSnapshot,
  agentZfsDestroyDataset,
  agentZfsRecv,
  agentZfsSendStream,
  agentZfsSnapshot,
  type AgentNode,
} from "../node-agent";
import { MOVE_SNAPSHOT_RE, parseVmDataset } from "./plan";

export type ZfsDatasetInfo =
  | { exists: false }
  | { exists: true; usedBytes: number; referencedBytes: number; volsizeBytes: number; snapshots: string[] };

export type ZfsHost = {
  label: string;
  dataset(dataset: string): Promise<ZfsDatasetInfo>;
  snapshot(dataset: string, snap: string): Promise<void>;
  deleteSnapshot(dataset: string, snap: string): Promise<void>;
  /** Destroys the dataset and its snapshots. Implementations refuse a dataset whose vmid has a VM config on that host. */
  destroyDataset(dataset: string): Promise<void>;
  /** zstd-compressed `zfs send [-i @from] dataset@snap`. */
  sendStream(dataset: string, snap: string, from?: string | null): Promise<Readable>;
  /** `zstd -d | zfs receive -F -u dataset` fed from `body`. Resolves on exit 0. */
  recv(dataset: string, body: Readable): Promise<void>;
};

function assertDataset(dataset: string): void {
  if (!parseVmDataset(dataset)) throw new Error(`refusing unexpected dataset name ${JSON.stringify(dataset)}`);
}
function assertSnap(snap: string): void {
  if (!MOVE_SNAPSHOT_RE.test(snap)) throw new Error(`refusing unexpected snapshot name ${JSON.stringify(snap)}`);
}

type Runner = (argv: string[]) => Promise<string>;
type Spawner = (argv: string[]) => import("node:child_process").ChildProcess;

function execArgv(cmd: string, args: string[], timeoutMs = 60_000): Promise<string> {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, args, { stdio: ["ignore", "pipe", "pipe"] });
    let out = "";
    let err = "";
    const timer = setTimeout(() => child.kill("SIGKILL"), timeoutMs);
    child.stdout.on("data", (d) => (out += d.toString()));
    child.stderr.on("data", (d) => (err += d.toString().slice(0, 2000)));
    child.on("error", (e) => {
      clearTimeout(timer);
      reject(e);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      if (code === 0) resolve(out);
      else reject(new Error(`${cmd} ${args.slice(0, 3).join(" ")}… exited ${code}: ${err.trim().slice(0, 400)}`));
    });
  });
}

/**
 * Build a host out of two primitives: `run(argv)` executes `zfs …`/`test …`
 * and returns stdout; `spawnCmd(argv)` starts a long-running process whose
 * stdin/stdout are streams. Local and SSH differ only in how argv is wrapped.
 */
function commandZfsHost(label: string, run: Runner, spawnCmd: Spawner): ZfsHost {
  const vmConfigExists = async (vmid: number) => {
    try {
      await run(["test", "-e", `/etc/pve/qemu-server/${vmid}.conf`]);
      return true;
    } catch {
      return false;
    }
  };
  return {
    label,
    async dataset(dataset) {
      assertDataset(dataset);
      let line: string;
      try {
        line = await run(["zfs", "list", "-Hp", "-o", "used,referenced,volsize", dataset]);
      } catch (e: any) {
        if (/does not exist/.test(String(e?.message))) return { exists: false };
        throw e;
      }
      const [used, referenced, volsize] = line.trim().split(/\s+/).map(Number);
      const snapsRaw = await run(["zfs", "list", "-Hp", "-t", "snapshot", "-o", "name", "-d", "1", dataset]).catch(() => "");
      const snapshots = snapsRaw
        .split("\n")
        .map((s) => s.trim())
        .filter(Boolean)
        .map((s) => s.slice(s.indexOf("@") + 1));
      return { exists: true, usedBytes: used, referencedBytes: referenced, volsizeBytes: volsize, snapshots };
    },
    async snapshot(dataset, snap) {
      assertDataset(dataset);
      assertSnap(snap);
      await run(["zfs", "snapshot", `${dataset}@${snap}`]);
    },
    async deleteSnapshot(dataset, snap) {
      assertDataset(dataset);
      assertSnap(snap);
      try {
        await run(["zfs", "destroy", `${dataset}@${snap}`]);
      } catch (e: any) {
        if (!/does not exist/.test(String(e?.message))) throw e;
      }
    },
    async destroyDataset(dataset) {
      assertDataset(dataset);
      const { vmid } = parseVmDataset(dataset)!;
      if (await vmConfigExists(vmid)) {
        throw new Error(`refusing to destroy ${dataset}: vm ${vmid} has a config on ${label} — destroy it through Proxmox`);
      }
      try {
        await run(["zfs", "destroy", "-r", dataset]);
      } catch (e: any) {
        if (!/does not exist/.test(String(e?.message))) throw e;
      }
    },
    async sendStream(dataset, snap, from) {
      assertDataset(dataset);
      assertSnap(snap);
      if (from) assertSnap(from);
      const zfsArgs = ["zfs", "send", "-L", "-e", ...(from ? ["-i", `${dataset}@${from}`] : []), `${dataset}@${snap}`];
      const send = spawnCmd(zfsArgs);
      const zstd = spawn("nice", ["-n", "10", "zstd", "-3", "-q", "-T1"], { stdio: ["pipe", "pipe", "pipe"] });
      const out = new PassThrough();
      let sendErr = "";
      send.stderr?.on("data", (d) => (sendErr += d.toString().slice(0, 1000)));
      send.on("close", (code) => {
        if (code !== 0) out.destroy(new Error(`zfs send ${dataset}@${snap} exited ${code}: ${sendErr.trim()}`));
      });
      send.stdout!.pipe(zstd.stdin);
      zstd.stdout.pipe(out);
      zstd.on("close", (code) => {
        if (code !== 0) out.destroy(new Error(`zstd exited ${code}`));
      });
      return out;
    },
    async recv(dataset, body) {
      assertDataset(dataset);
      const { vmid } = parseVmDataset(dataset)!;
      if (await vmConfigExists(vmid)) throw new Error(`refusing zfs receive into ${dataset}: vm ${vmid} already has a config on ${label}`);
      const zstd = spawn("zstd", ["-d", "-q", "-T0"], { stdio: ["pipe", "pipe", "pipe"] });
      const recv = spawnCmd(["zfs", "receive", "-F", "-u", dataset]);
      let recvErr = "";
      recv.stderr?.on("data", (d) => (recvErr += d.toString().slice(0, 1000)));
      const done = new Promise<void>((resolve, reject) => {
        recv.on("error", reject);
        recv.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`zfs receive exited ${code}: ${recvErr.trim()}`))));
      });
      zstd.stdout.pipe(recv.stdin!);
      try {
        await pipeline(body, zstd.stdin);
        await done;
      } catch (e) {
        try {
          zstd.kill("SIGKILL");
        } catch {
          /* gone */
        }
        try {
          recv.kill("SIGKILL");
        } catch {
          /* gone */
        }
        throw e;
      }
    },
  };
}

/** The primary itself. */
export function localZfsHost(label = "primary"): ZfsHost {
  return commandZfsHost(
    label,
    (argv) => execArgv(argv[0], argv.slice(1)),
    (argv) => spawn(argv[0], argv.slice(1), { stdio: ["pipe", "pipe", "pipe"] }),
  );
}

/** Transition fallback: root SSH to a node (argv only, BatchMode, no shell string). */
export function sshZfsHost(node: { name: string; publicIp: string }): ZfsHost {
  const base = ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", "-o", "StrictHostKeyChecking=accept-new", `root@${node.publicIp}`, "--"];
  return commandZfsHost(
    `${node.name} (ssh)`,
    (argv) => execArgv("ssh", [...base, ...argv]),
    (argv) => spawn("ssh", [...base, ...argv], { stdio: ["pipe", "pipe", "pipe"] }),
  );
}

/** A non-primary node via its node-agent (v2). */
