/**
 * Dedicated-IP carry-over for VM moves — the OVH half.
 *
 * An OVH failover IP is routed to exactly one dedicated server at a time and
 * reaches a VM through a per-server Virtual MAC. Moving a VM between two OVH
 * boxes therefore needs three provider-side steps, in this order and only as
 * the LAST step before the target starts (so everything before it is a plain
 * local rollback):
 *
 *   1. `GET /ip/{ip}/move` — the list of services the IP MAY move to. OVH only
 *      lists same-campus destinations (verified live 2026-10-01: a Singapore
 *      IP lists ns5002569/ns5013314/ns564103 and not the Beauharnois box), so
 *      this is the authoritative "same zone" guard. We also compare the two
 *      servers' `datacenter` fields as a belt-and-braces check.
 *   2. `POST /ip/{ip}/move {to}` — asynchronous; returns a task we poll via
 *      `GET /ip/{ip}/task/{id}` until `done` (or `error`/`cancelled`).
 *   3. `POST /dedicated/server/{target}/virtualMac {ipAddress,type:"ovh",…}`
 *      — a NEW Virtual MAC on the target server (the old one stays bound to
 *      the source server's object and is deleted at cleanup). The MAC string
 *      is what the target VM's net0 must carry.
 *
 * Rollback = the same three steps back toward the source. Hetzner nodes are
 * not supported for a dedicated-IP move yet (the engine refuses at preflight):
 * Hetzner's Robot has no "move IP" call — the IP must be re-ordered against
 * the other server — and the fleet currently has one Hetzner node, so a
 * dedicated-IP move involving it would be a different, manual runbook.
 */
import { ovh, ovhApi } from "../ovh";
import { ipMoveDestinationAllowed, type OvhMoveDestinations } from "./plan";

const IPV4 = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
const SERVICE_RE = /^[a-z0-9][a-z0-9.-]{2,80}$/;

function assertIp(ip: string): void {
  if (!IPV4.test(ip)) throw new Error(`refusing non-IPv4 address ${JSON.stringify(ip)}`);
}
function assertService(s: string): void {
  if (!SERVICE_RE.test(s)) throw new Error(`refusing unexpected OVH service name ${JSON.stringify(s)}`);
}

export type OvhIpFacts = {
  routedTo: string | null;
  campus: string | null;
  type: string | null;
  destinations: OvhMoveDestinations;
};

export async function ovhIpFacts(ip: string): Promise<OvhIpFacts> {
  assertIp(ip);
  const block = `${ip}/32`;
  const info = await ovhApi.ipInfo(block);
  const destinations: OvhMoveDestinations = await ovh("GET", `/ip/${encodeURIComponent(block)}/move`).catch(() => ({}));
  return {
    routedTo: info?.routedTo?.serviceName ?? null,
    campus: info?.campus ?? null,
    type: info?.type ?? null,
    destinations,
  };
}

export async function ovhServerDatacenter(service: string): Promise<string | null> {
  assertService(service);
  const d = await ovhApi.server(service).catch(() => null);
  return d?.datacenter ?? null;
}

/** Everything preflight needs to know before promising an IP can travel. */
export async function ovhIpMovePreflight(ip: string, sourceService: string, targetService: string): Promise<{ ok: boolean; detail: string }> {
  assertService(sourceService);
  assertService(targetService);
  const facts = await ovhIpFacts(ip);
  if (facts.routedTo !== sourceService) {
    return { ok: false, detail: `${ip} is routed to ${facts.routedTo ?? "nobody"}, not the source node's service ${sourceService}` };
  }
  if (facts.type !== "failover" && facts.type !== "additional") {
    return { ok: false, detail: `${ip} is an OVH "${facts.type}" IP — only failover/additional IPs can move` };
  }
  if (!ipMoveDestinationAllowed(facts.destinations, targetService)) {
    const listed = (facts.destinations.dedicatedServer ?? []).map((d) => d.service).join(", ") || "none";
    return { ok: false, detail: `OVH will not move ${ip} to ${targetService} (campus ${facts.campus ?? "?"}); allowed destinations: ${listed}` };
  }
  const [srcDc, dstDc] = await Promise.all([ovhServerDatacenter(sourceService), ovhServerDatacenter(targetService)]);
  if (srcDc && dstDc && srcDc.replace(/\d+$/, "") !== dstDc.replace(/\d+$/, "")) {
    return { ok: false, detail: `source datacenter ${srcDc} and target ${dstDc} are different campuses` };
  }
  return { ok: true, detail: `${ip} (${facts.campus ?? "?"}) may move ${sourceService} → ${targetService}; datacenters ${srcDc ?? "?"}/${dstDc ?? "?"}` };
}

/** Where a failover IP is routed right now — used to make the move idempotent. */
export async function ovhIpRoutedTo(ip: string): Promise<string | null> {
  return (await ovhIpFacts(ip)).routedTo;
}

/**
 * Route `ip` to `targetService` and wait for OVH's task to finish. Idempotent:
 * if the IP is already routed there, returns immediately. Returns the task id
 * (or null when nothing had to be done).
 */
export async function ovhMoveIp(ip: string, targetService: string, opts?: { timeoutMs?: number; pollMs?: number }): Promise<number | null> {
  assertIp(ip);
  assertService(targetService);
  const block = `${ip}/32`;
  if ((await ovhIpRoutedTo(ip)) === targetService) return null;
  const task = await ovh("POST", `/ip/${encodeURIComponent(block)}/move`, { to: targetService });
  const taskId: number | undefined = task?.taskId;
  const timeoutMs = opts?.timeoutMs ?? 10 * 60_000;
  const pollMs = opts?.pollMs ?? 5_000;
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    await new Promise((r) => setTimeout(r, pollMs));
    if (taskId !== undefined) {
      const t = await ovh("GET", `/ip/${encodeURIComponent(block)}/task/${taskId}`).catch(() => null);
      const status = t?.status;
      if (status === "done") break;
      if (status === "error" || status === "cancelled") throw new Error(`OVH IP move task ${taskId} ended with status ${status}`);
    }
    if ((await ovhIpRoutedTo(ip)) === targetService) break;
  }
  if ((await ovhIpRoutedTo(ip)) !== targetService) throw new Error(`OVH did not finish routing ${ip} to ${targetService} within ${Math.round(timeoutMs / 1000)}s`);
  return taskId ?? null;
}

/** Find the Virtual MAC bound to `ip` on `service`, if any. */
export async function ovhFindVirtualMac(service: string, ip: string): Promise<string | null> {
  assertService(service);
  assertIp(ip);
  const macs: string[] = await ovhApi.virtualMacs(service).catch(() => []);
  for (const m of macs) {
    const ips: string[] = await ovh("GET", `/dedicated/server/${service}/virtualMac/${m}/virtualAddress`).catch(() => []);
    if (ips.includes(ip)) return m;
  }
  return null;
}

/** Ensure a Virtual MAC for `ip` exists on `service` and return it (creation is async on OVH's side; polled). */
export async function ovhEnsureVirtualMac(service: string, ip: string, vmName: string, opts?: { attempts?: number; pollMs?: number }): Promise<string> {
  assertService(service);
  assertIp(ip);
  let mac = await ovhFindVirtualMac(service, ip);
  if (mac) return mac;
  await ovhApi.createVirtualMac(service, ip, vmName.replace(/[^a-zA-Z0-9-]/g, "").slice(0, 40) || "nxeon-move");
  const attempts = opts?.attempts ?? 40;
  const pollMs = opts?.pollMs ?? 3_000;
  for (let i = 0; i < attempts && !mac; i++) {
    await new Promise((r) => setTimeout(r, pollMs));
    mac = await ovhFindVirtualMac(service, ip);
  }
  if (!mac) throw new Error(`Virtual MAC for ${ip} on ${service} not bound after creation (OVH task still pending)`);
  return mac;
}

/** Best-effort removal of the Virtual MAC that carried `ip` on `service` (cleanup / rollback). */
export async function ovhReleaseVirtualMac(service: string, ip: string, mac: string | null): Promise<void> {
  assertService(service);
  assertIp(ip);
  const target = mac ?? (await ovhFindVirtualMac(service, ip));
  if (!target) return;
  await ovh("DELETE", `/dedicated/server/${service}/virtualMac/${target}/virtualAddress/${ip}`).catch(() => {});
  await ovh("DELETE", `/dedicated/server/${service}/virtualMac/${target}`).catch(() => {});
}

