    const listed = (facts.destinations.dedicatedServer ?? []).map((d) => d.service).join(", ") || "none";
    return { ok: false, detail: `OVH will not move ${ip} to ${targetService} (campus ${facts.campus ?? "?"}); allowed destinations: ${listed}` };
  }
  const [srcDc, dstDc] = await Promise.all([ovhServerDatacenter(sourceService), ovhServerDatacenter(targetService)]);
  if (srcDc && dstDc && srcDc.replace(/\d+$/, "") !== dstDc.replace(/\d+$/, "")) {
    return { ok: false, detail: `source datacenter ${srcDc} and target ${dstDc} are different campuses` };
  }
  return { ok: true, detail: `${ip} (${facts.campus ?? "?"}) may move ${sourceService} → ${targetService}; datacenters ${srcDc ?? "?"}/${dstDc ?? "?"}` };
}

/** Where a failover IP is routed right now — used to make the move idempotent. */
export async function ovhIpRoutedTo(ip: string): Promise<string | null> {
  return (await ovhIpFacts(ip)).routedTo;
}

/**
 * Route `ip` to `targetService` and wait for OVH's task to finish. Idempotent:
 * if the IP is already routed there, returns immediately. Returns the task id
 * (or null when nothing had to be done).
 */
export async function ovhMoveIp(ip: string, targetService: string, opts?: { timeoutMs?: number; pollMs?: number }): Promise<number | null> {
  assertIp(ip);
  assertService(targetService);
  const block = `${ip}/32`;
  if ((await ovhIpRoutedTo(ip)) === targetService) return null;
  const task = await ovh("POST", `/ip/${encodeURIComponent(block)}/move`, { to: targetService });
  const taskId: number | undefined = task?.taskId;
  const timeoutMs = opts?.timeoutMs ?? 10 * 60_000;
  const pollMs = opts?.pollMs ?? 5_000;
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    await new Promise((r) => setTimeout(r, pollMs));
    if (taskId !== undefined) {
      const t = await ovh("GET", `/ip/${encodeURIComponent(block)}/task/${taskId}`).catch(() => null);
      const status = t?.status;
      if (status === "done") break;
      if (status === "error" || status === "cancelled") throw new Error(`OVH IP move task ${taskId} ended with status ${status}`);
    }
    if ((await ovhIpRoutedTo(ip)) === targetService) break;
  }
  if ((await ovhIpRoutedTo(ip)) !== targetService) throw new Error(`OVH did not finish routing ${ip} to ${targetService} within ${Math.round(timeoutMs / 1000)}s`);
  return taskId ?? null;
}

/** Find the Virtual MAC bound to `ip` on `service`, if any. */
export async function ovhFindVirtualMac(service: string, ip: string): Promise<string | null> {
  assertService(service);
  assertIp(ip);
  const macs: string[] = await ovhApi.virtualMacs(service).catch(() => []);
  for (const m of macs) {
    const ips: string[] = await ovh("GET", `/dedicated/server/${service}/virtualMac/${m}/virtualAddress`).catch(() => []);
    if (ips.includes(ip)) return m;
  }
  return null;
}

/** Ensure a Virtual MAC for `ip` exists on `service` and return it (creation is async on OVH's side; polled). */
export async function ovhEnsureVirtualMac(service: string, ip: string, vmName: string, opts?: { attempts?: number; pollMs?: number }): Promise<string> {
  assertService(service);
  assertIp(ip);
  let mac = await ovhFindVirtualMac(service, ip);
  if (mac) return mac;
  await ovhApi.createVirtualMac(service, ip, vmName.replace(/[^a-zA-Z0-9-]/g, "").slice(0, 40) || "nxeon-move");
  const attempts = opts?.attempts ?? 40;
  const pollMs = opts?.pollMs ?? 3_000;
  for (let i = 0; i < attempts && !mac; i++) {
    await new Promise((r) => setTimeout(r, pollMs));
    mac = await ovhFindVirtualMac(service, ip);
  }
  if (!mac) throw new Error(`Virtual MAC for ${ip} on ${service} not bound after creation (OVH task still pending)`);
  return mac;
}

/** Best-effort removal of the Virtual MAC that carried `ip` on `service` (cleanup / rollback). */
export async function ovhReleaseVirtualMac(service: string, ip: string, mac: string | null): Promise<void> {
  assertService(service);
  assertIp(ip);
  const target = mac ?? (await ovhFindVirtualMac(service, ip));
  if (!target) return;
  await ovh("DELETE", `/dedicated/server/${service}/virtualMac/${target}/virtualAddress/${ip}`).catch(() => {});
  await ovh("DELETE", `/dedicated/server/${service}/virtualMac/${target}`).catch(() => {});
}

