function agentAuthOrThrow(node: AgentNode): string {
  const token = nodeAgentToken(node);
  if (!token) throw new NodeAgentError(`node "${node.name}" has no agent token configured — see /admin/nodes/${node.id}`, node.name);
  return token;
}

/** Pipe a (zstd-compressed) zfs send stream INTO this node's `zfs receive`. Resolves when the agent confirms the receive exited 0. */
export async function agentZfsRecv(node: AgentNode, dataset: string, body: import("node:stream").Readable): Promise<void> {
  const token = agentAuthOrThrow(node);
  const url = `https://${node.publicIp}:${node.agentPort}/v1/zfs/recv?dataset=${encodeURIComponent(dataset)}`;
  let res: Awaited<ReturnType<typeof undiciFetch>>;
  try {
    res = await undiciFetch(url, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/octet-stream" },
      body: body as any,
      duplex: "half",
      dispatcher: insecureAgent,
      signal: undefined,
    } as any);
  } catch (e: any) {
    throw new NodeAgentError(`zfs recv to "${node.name}" failed in transit: ${e?.message ?? e}`, node.name);
  }
  const text = await res.text().catch(() => "");
  if (!res.ok) throw new NodeAgentError(`node-agent on "${node.name}" rejected zfs recv (${res.status}): ${text.slice(0, 300)}`, node.name);
}

/** Open a (zstd-compressed) zfs send stream FROM this node. The caller must consume it fully; a truncated body means the remote send failed. */
export async function agentZfsSendStream(node: AgentNode, dataset: string, snap: string, from?: string | null): Promise<import("node:stream").Readable> {
  const token = agentAuthOrThrow(node);
  const qs = new URLSearchParams({ dataset, snap, ...(from ? { from } : {}) });
  const url = `https://${node.publicIp}:${node.agentPort}/v1/zfs/send?${qs}`;
  let res: Awaited<ReturnType<typeof undiciFetch>>;
  try {
    res = await undiciFetch(url, { method: "GET", headers: { Authorization: `Bearer ${token}` }, dispatcher: insecureAgent, signal: undefined });
  } catch (e: any) {
    throw new NodeAgentError(`could not open zfs send from "${node.name}": ${e?.message ?? e}`, node.name);
  }
  if (!res.ok || !res.body) {
    const text = await res.text().catch(() => "");
    throw new NodeAgentError(`node-agent on "${node.name}" refused zfs send (${res.status}): ${text.slice(0, 300)}`, node.name);
  }
  const { Readable } = await import("node:stream");
  return Readable.fromWeb(res.body as any);
}

