export async function buildMovePlan(input: PreflightInput): Promise<MovePlan> {
  const server = await loadMoveServer(input.serverId);
  if (!server) throw new Error(`server ${input.serverId} not found`);
  const target = await loadMoveNode(input.targetNodeId);
  if (!target) throw new Error(`target node ${input.targetNodeId} not found`);
  const source = server.node ?? (await db.node.findFirst({ where: { isPrimary: true }, select: MOVE_NODE_SELECT }));
  if (!source) throw new Error("server has no node and no primary node exists");

  const checks: PreflightCheck[] = [];
  const check = (id: string, ok: boolean, detail: string, blocking = true) => checks.push({ id, ok, blocking, detail });

  // ---- server-side eligibility ------------------------------------------------
  check("different-node", source.id !== target.id, source.id === target.id ? "target is the server's current node" : `${source.name} → ${target.name}`);
  check("target-enabled", target.enabled && target.status === "ONLINE", `${target.name}: enabled=${target.enabled} status=${target.status}`);
  check("server-has-vm", !!server.vmid, server.vmid ? `vmid ${server.vmid}` : "server has no VM yet");
  check("server-status", ["RUNNING", "STOPPED"].includes(server.status), `status ${server.status}`);
  const volumes = await db.volume.count({ where: { serverId: server.id } });
  check("no-volumes", volumes === 0, volumes ? `${volumes} block-storage volume(s) pinned — only single-disk VMs move` : "no block-storage volumes");
  const inflight = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] }, type: { notIn: ["VM_MOVE"] } } });
  check("no-other-jobs", inflight === 0, inflight ? `${inflight} other job(s) queued/running for this server` : "no other jobs in flight");
  const activeMoves = await db.vmMove.count({ where: { serverId: server.id, status: { in: ["RUNNING"] } } });
  check("no-active-move", activeMoves === 0, activeMoves ? "a move is already running for this server" : "no other move running");
  const internal = server.dedicatedIp?.purpose === "INTERNAL";
  check("not-internal", !internal, internal ? "dedicated IP is marked INTERNAL (company infrastructure)" : "customer server");

  const planRamMB = server.gamePlan?.ramMB ?? server.plan.ramMB;
  const planVcpu = server.gamePlan?.cpuCores ?? server.plan.cpuCores;

  // ---- source VM facts ----------------------------------------------------------
  const srcConn = pveFor(source);
  const tgtConn = pveFor(target);
  let carried: Record<string, string> = {};
  let diskSizeGB = server.gamePlan?.diskGB ?? server.plan.diskGB;
  let sourceStorage = source.storageNvme;
  let sourcePool = "";
  let targetPool = "";
  let sourceUsedBytes = 0;
  let sourceDataset = "";
  let targetDataset = "";
  let snapshotNames: string[] = [];
  if (server.vmid) {
    try {
      const cfg = await srcConn.get(`/nodes/${srcConn.node}/qemu/${server.vmid}/config`);
      const snaps: any[] = await srcConn.get(`/nodes/${srcConn.node}/qemu/${server.vmid}/snapshot`).catch(() => []);
      snapshotNames = (snaps ?? []).map((s) => String(s?.name)).filter((n) => n && n !== "current");
      const insp = inspectSourceConfig(cfg ?? {});
      carried = insp.carried;
      check("single-disk-config", insp.refusedKeys.length === 0, insp.refusedKeys.length ? `config has ${insp.refusedKeys.join(", ")} — only a plain scsi0 + cloud-init VM moves` : "plain scsi0 + cloud-init drive");
      check("has-scsi0", !!insp.disk, insp.disk ? `scsi0 = ${insp.disk.storage}:${insp.disk.volume} (${insp.disk.sizeGB} GB)` : "no scsi0 disk found");
      check("has-cloudinit-drive", insp.hasCloudInitDrive, insp.hasCloudInitDrive ? "cloud-init drive present (re-IP is possible)" : "no cloud-init drive — the guest's network could not be re-pointed");
      check(
        "no-snapshots",
        snapshotNames.length === 0 || !!input.allowDropSnapshots,
        snapshotNames.length ? `${snapshotNames.length} Proxmox snapshot(s) (${snapshotNames.join(", ")}) would NOT be carried over${input.allowDropSnapshots ? " — accepted by the operator" : ""}` : "no snapshots to lose",
      );
      if (insp.disk) {
        sourceStorage = insp.disk.storage;
        if (insp.disk.sizeGB) diskSizeGB = insp.disk.sizeGB;
        sourcePool = await storagePool(srcConn, sourceStorage);
        sourceDataset = `${sourcePool}/${insp.disk.volume}`;
        const zfs = zfsHostFor(source);
        const info = await zfs.dataset(sourceDataset);
        check("source-dataset", info.exists, info.exists ? `${sourceDataset}: ${(info.usedBytes / 2 ** 30).toFixed(1)} GB used of ${(info.volsizeBytes / 2 ** 30).toFixed(0)} GB` : `${sourceDataset} not found via ${zfs.label}`);
        if (info.exists) sourceUsedBytes = info.usedBytes;
      }
    } catch (e: any) {
      check("source-readable", false, `could not read the source VM: ${e?.message ?? e}`);
    }
  }

  // ---- target facts -------------------------------------------------------------
  let targetFacts: NodeCapacityFacts | null = null;
  try {
    targetPool = await storagePool(tgtConn, target.storageNvme);
    targetFacts = await nodeCapacityFacts(target, tgtConn);
    checks.push(...capacityChecks(targetFacts, planRamMB, planVcpu, sourceUsedBytes, diskSizeGB));
  } catch (e: any) {
    check("target-readable", false, `could not read the target node: ${e?.message ?? e}`);
  }
  if (!target.isPrimary) {
    try {
      const h = await agentHealth(target);
      const transport = process.env.VM_MOVE_TRANSPORT ?? "agent";
      check("target-agent", !!h?.ok && ((h.version ?? 1) >= 2 || transport === "ssh"), `node-agent on ${target.name}: ok=${!!h?.ok} version=${h?.version ?? 1}${(h?.version ?? 1) < 2 ? " (v2 required for the zfs transport; VM_MOVE_TRANSPORT=ssh is the fallback)" : ""}`);
    } catch (e: any) {
      check("target-agent", (process.env.VM_MOVE_TRANSPORT ?? "agent") === "ssh", `node-agent on ${target.name} unreachable: ${e?.message ?? e}`);
    }
  }
  if (!source.isPrimary) {
    try {
      const h = await agentHealth(source);
      const transport = process.env.VM_MOVE_TRANSPORT ?? "agent";
      check("source-agent", !!h?.ok && ((h.version ?? 1) >= 2 || transport === "ssh"), `node-agent on ${source.name}: ok=${!!h?.ok} version=${h?.version ?? 1}`);
    } catch (e: any) {
      check("source-agent", (process.env.VM_MOVE_TRANSPORT ?? "agent") === "ssh", `node-agent on ${source.name} unreachable: ${e?.message ?? e}`);
    }
  }

  // ---- target vmid: brand-new, fleet-wide ----------------------------------------
  let targetVmid = 0;
  try {
    const { sets, unreachable } = await fleetVmidSets(tgtConn, backupStorageFor(target));
    targetVmid = pickMoveTargetVmid(sets);
    check("fleet-vmid-visibility", unreachable.length === 0, unreachable.length ? `could not list VMs on: ${unreachable.join(", ")} — a brand-new id cannot be guaranteed` : `every node answered; new vmid ${targetVmid}`);
    if (targetPool) targetDataset = datasetFor(targetPool, targetVmid);
    const existing = targetDataset ? await zfsHostFor(target).dataset(targetDataset).catch(() => null) : null;
    check("target-dataset-free", !existing || !existing.exists, existing?.exists ? `${targetDataset} already exists on ${target.name}` : `${targetDataset || "(target dataset)"} is free`);
  } catch (e: any) {
    check("fleet-vmid", false, `could not allocate a target vmid: ${e?.message ?? e}`);
  }

  // ---- addressing ---------------------------------------------------------------
  let addressing: MoveAddressing;
  let targetBridge = "vmbr0";
  if (server.dedicatedIp && !internal) {
    const addr = server.dedicatedIp.address;
    const ovhBoth = source.provider === "OVH" && target.provider === "OVH";
    check("ip-provider", ovhBoth, ovhBoth ? "OVH → OVH (failover IP move supported)" : `dedicated-IP moves are OVH→OVH only (source ${source.provider}, target ${target.provider})`);
    check("same-region", source.region === target.region, `${source.region} → ${target.region}`);
    check("provider-service-ids", !!source.providerServerId && !!target.providerServerId, `source service ${source.providerServerId ?? "?"}, target service ${target.providerServerId ?? "?"}`);
    if (ovhBoth && source.providerServerId && target.providerServerId) {
      try {
        const r = await ovhIpMovePreflight(addr, source.providerServerId, target.providerServerId);
        check("ovh-ip-move-allowed", r.ok, r.detail);
      } catch (e: any) {
        check("ovh-ip-move-allowed", false, `OVH API: ${e?.message ?? e}`);
      }
    }
    addressing = {
      kind: "DEDICATED",
      address: addr,
      sourceGateway: ovhGatewayOf(source.publicIp),
      targetGateway: ovhGatewayOf(target.publicIp),
      sourceService: source.providerServerId ?? "",
      targetService: target.providerServerId ?? "",
      sourceVirtualMac: server.dedicatedIp.virtualMac,
    };
  } else {
    targetBridge = target.bridge;
    let planned = { ip: "", gateway: gatewayIp(target.subnetPrefix) };
    try {
      planned = await planTargetPrivateIp(target.id);
      check("target-private-ip", true, `planned ${planned.ip} (gw ${planned.gateway}); claimed atomically at COMMIT`);
    } catch (e: any) {
      check("target-private-ip", false, `${e?.message ?? e}`);
    }
    check("public-address-change", true, `public IP changes ${source.publicIp} → ${target.publicIp}; SSH port ${server.sshPort ?? "—"} and ${server.portForwards.length} forward(s) keep their numbers${server.subdomain ? `; subdomain ${server.subdomain} is repointed` : ""}`, false);
    addressing = {
      kind: "NAT",
      sourcePrivateIp: server.ipAddress ?? "",
      targetPrivateIpPlanned: planned.ip,
      targetGateway: planned.gateway,
      sshPort: server.sshPort,
      forwardPorts: server.portForwards.map((f) => f.publicPort),
      sourcePublicIp: source.publicIp,
      targetPublicIp: target.publicIp,
    };
  }

  const est = estimateDurations(sourceUsedBytes);
  const ok = checks.every((c) => c.ok || !c.blocking);
  return {
    version: 1,
    serverId: server.id,
    hostname: server.hostname,
    sourceNodeId: source.id,
    sourceNodeName: source.name,
    targetNodeId: target.id,
    targetNodeName: target.name,
    sourceVmid: server.vmid ?? 0,
    targetVmid,
    planRamMB,
    planVcpu,
    diskSizeGB,
    sourceUsedBytes,
    sourceDataset,
    targetDataset,
    sourceStorage,
    targetStorage: target.storageNvme,
    targetSnippetStorage: snippetStorageFor(target),
    targetBridge,
    addressing,
    carriedConfig: carried,
    target: targetFacts ?? {
      nodeId: target.id,
      name: target.name,
      region: target.region,
      realAvailRamMB: 0,
      realTotalRamMB: 0,
      committedRamMB: 0,
      capacityRamMB: target.capacityRamMB,
      poolFreeBytes: 0,
      poolTotalBytes: 0,
      cpuThreads: 0,
      committedVcpu: 0,
      cpuLoad: 0,
    },
    checks,
    ok,
    estimatedDowntimeSec: est.downtimeSec,
    estimatedFullSendSec: est.fullSendSec,
    createdAt: new Date().toISOString(),
  };
}

/** OVH's failover gateway convention for the node that hosts the VM: <node /24>.254. */
function ovhGatewayOf(nodePublicIp: string): string {
  const p = nodePublicIp.split(".");
  return p.length === 4 ? `${p[0]}.${p[1]}.${p[2]}.254` : ovhGateway();
}

