import { test } from "node:test";
import assert from "node:assert/strict";
import {
  buildTargetConfig,
  capacityChecks,
  classifyCandidate,
  datasetFor,
  estimateDurations,
  inspectSourceConfig,
  ipMoveDestinationAllowed,
  macFromNet0,
  moveSafeVendorSnippet,
  nextPhase,
  parseScsi0,
  parseVmDataset,
  pickMoveTargetVmid,
  rankMoveCandidates,
  rollbackAllowed,
  rollbackSteps,
  type CandidateInput,
} from "../lib/vm-move/plan.ts";
import type { NodeCapacityFacts } from "../lib/vm-move/types.ts";

// ---------------------------------------------------------------------------
// VMID allocation — brand-new, fleet-wide
// ---------------------------------------------------------------------------

test("pickMoveTargetVmid is strictly above every id the fleet has ever seen", () => {
  const live = [105, 106, 109, 110, 112, 115, 116, 118, 120, 121, 200, 8000, 9000, 9010]; // the primary today
  const node4 = [128, 130, 131, 133, 140, 501, 600, 9550];
  const node5 = [101, 117, 139, 142, 143];
  const dbArchived = [111, 113, 119, 150]; // destroyed servers whose rows/archives survive
  const id = pickMoveTargetVmid([live, node4, node5, dbArchived]);
  assert.equal(id, 601, "highest customer-band id is 600 → 601");
  for (const s of [live, node4, node5, dbArchived]) for (const taken of s) assert.notEqual(id, taken);
});

test("pickMoveTargetVmid never hands out a recycled lower id even if it is free", () => {
  // 102–140 are "free" on this node but 141 was used once; the next id must be 142.
  assert.equal(pickMoveTargetVmid([[100, 101, 141]]), 142);
});

test("pickMoveTargetVmid skips the 9000–9999 template band", () => {
  assert.equal(pickMoveTargetVmid([[8999]]), 10000, "8999 → next is 9000 which is templates → 10000");
  assert.equal(pickMoveTargetVmid([[8998]]), 8999);
});

test("pickMoveTargetVmid ignores infra ids above the customer band when picking the base", () => {
  // nxeon-mail at 8000 and the relay at 9010 must not push customers to 8001+.
  assert.equal(pickMoveTargetVmid([[105, 8000, 9010]]), 106);
});

test("pickMoveTargetVmid tolerates garbage and empty sets", () => {
  assert.equal(pickMoveTargetVmid([[], [NaN as unknown as number, 0, 50], new Set([200])]), 201);
  assert.equal(pickMoveTargetVmid([]), 100);
});

// ---------------------------------------------------------------------------
// Datasets
// ---------------------------------------------------------------------------

test("datasetFor / parseVmDataset round-trip and refuse anything odd", () => {
  assert.equal(datasetFor("data/vms", 109), "data/vms/vm-109-disk-0");
  assert.deepEqual(parseVmDataset("rpool/data/vm-601-disk-0"), { pool: "rpool/data", vmid: 601, disk: 0 });
  assert.equal(parseVmDataset("data/vm-601-disk-0; rm -rf /"), null);
  assert.equal(parseVmDataset("vm-601-disk-0"), null, "no pool");
  assert.equal(parseVmDataset("data/vms/base-9000-disk-0"), null, "templates are not vm-*");
  assert.throws(() => datasetFor("Data Pool", 109));
  assert.throws(() => datasetFor("data", 99));
});

// ---------------------------------------------------------------------------
// Capacity
// ---------------------------------------------------------------------------

const sgp2: NodeCapacityFacts = {
  nodeId: "n3",
  name: "node-3",
  region: "sgp1",
  realAvailRamMB: 3000, // measured 2026-10-01: 3.0 GB available on a 31 GB host
  realTotalRamMB: 31862,
  committedRamMB: 28 * 1024,
  capacityRamMB: 23862,
  poolFreeBytes: 768 * 2 ** 30,
  poolTotalBytes: 928 * 2 ** 30,
  cpuThreads: 12,
  committedVcpu: 13,
  cpuLoad: 0.06,
};

test("capacityChecks blocks a move onto a host with no REAL headroom even when the pool is huge", () => {
  const checks = capacityChecks(sgp2, 2048, 1, 10 * 2 ** 30, 25);
  const ram = checks.find((c) => c.id === "target-real-ram")!;
  assert.equal(ram.ok, false);
  assert.equal(ram.blocking, true);
  const committed = checks.find((c) => c.id === "target-committed-ram")!;
  assert.equal(committed.ok, false, "28/23 GB over-committed already");
  const pool = checks.find((c) => c.id === "target-pool-space")!;
  assert.equal(pool.ok, true);
});

test("capacityChecks passes a roomy host and only warns on CPU", () => {
  const bhs1: NodeCapacityFacts = { ...sgp2, name: "node-5", realAvailRamMB: 26041, committedRamMB: 8 * 1024, capacityRamMB: 56070, cpuThreads: 12, committedVcpu: 14, cpuLoad: 0.1 };
  const checks = capacityChecks(bhs1, 8192, 3, 40 * 2 ** 30, 80);
  assert.ok(checks.filter((c) => c.blocking).every((c) => c.ok), JSON.stringify(checks));
  const cpu = checks.find((c) => c.id === "target-cpu")!;
  assert.equal(cpu.blocking, false);
});

test("capacityChecks refuses to fill a pool past the free-ratio floor", () => {
  const tight: NodeCapacityFacts = { ...sgp2, realAvailRamMB: 20000, committedRamMB: 1024, capacityRamMB: 56000, poolFreeBytes: 60 * 2 ** 30, poolTotalBytes: 358 * 2 ** 30 };
  const checks = capacityChecks(tight, 2048, 1, 30 * 2 ** 30, 50);
  assert.equal(checks.find((c) => c.id === "target-pool-space")!.ok, false, "30 GB into 60 GB free leaves 8% < 15%");
});

// ---------------------------------------------------------------------------
// Classification + ranking
// ---------------------------------------------------------------------------

const base: CandidateInput = {
  serverId: "s",
  hostname: "x",
  vmid: 120,
  nodeId: "p",
  status: "RUNNING",
  planRamMB: 8192,
  planVcpu: 3,
  diskGB: 50,
  hasDedicatedIp: false,
  internalIp: false,
  isFree: false,
  attachedVolumes: 0,
  subdomain: null,
  forwardCount: 1,
  gameFamily: "minecraft",
  realRssMB: 4600,
  realCpuPct: 20,
  daysToExpiry: 20,
  autoRenew: true,
  companyInfra: false,
};

test("classifyCandidate: dedicated IP → class A, NAT → class B, volumes/internal/no-vm → C", () => {
  assert.equal(classifyCandidate({ ...base, hasDedicatedIp: true }).klass, "A_DEDICATED_IP");
  assert.equal(classifyCandidate(base).klass, "B_NAT");
  assert.equal(classifyCandidate({ ...base, attachedVolumes: 1 }).klass, "C_MUST_STAY");
  assert.equal(classifyCandidate({ ...base, hasDedicatedIp: true, internalIp: true }).klass, "C_MUST_STAY");
  assert.equal(classifyCandidate({ ...base, vmid: null }).klass, "C_MUST_STAY");
  assert.equal(classifyCandidate({ ...base, status: "PROVISIONING" }).klass, "C_MUST_STAY");
  assert.equal(classifyCandidate({ ...base, companyInfra: true }).klass, "C_MUST_STAY");
});

test("rankMoveCandidates puts movable servers first, biggest real relief at the top, must-stay last", () => {
  const ranked = rankMoveCandidates([
    { ...base, serverId: "small", hostname: "mobilkit", planRamMB: 2048, realRssMB: 1380, realCpuPct: 5, hasDedicatedIp: true, diskGB: 25 },
    { ...base, serverId: "big", hostname: "blue", planRamMB: 8192, realRssMB: 4636, realCpuPct: 20 },
    { ...base, serverId: "infra", hostname: "hosting-1", hasDedicatedIp: true, internalIp: true, realRssMB: 2877 },
    { ...base, serverId: "expiring", hostname: "dst", realRssMB: 3800, realCpuPct: 34, daysToExpiry: 2, autoRenew: false, diskGB: 50 },
  ]);
  assert.equal(ranked[0].serverId, "big");
  assert.equal(ranked[ranked.length - 1].serverId, "infra");
  assert.equal(ranked[ranked.length - 1].klass, "C_MUST_STAY");
  const expiring = ranked.find((r) => r.serverId === "expiring")!;
  const big = ranked.find((r) => r.serverId === "big")!;
  assert.ok(expiring.risk > big.risk, "about-to-expire with auto-renew off is riskier to bother moving");
});

// ---------------------------------------------------------------------------
// Phase state machine
// ---------------------------------------------------------------------------

test("nextPhase resumes from the first incomplete phase and skips MOVE_IP for NAT", () => {
  assert.equal(nextPhase({}, { dedicated: false }), "SNAPSHOT_LIVE");
  assert.equal(nextPhase({ liveSnapshotName: "nxmove1-a" }, { dedicated: false }), "SEND_FULL");
  assert.equal(nextPhase({ liveSnapshotName: "x", fullSentAt: "t" }, { dedicated: true }), "STOP_SOURCE");
  const upToCreate = { liveSnapshotName: "x", fullSentAt: "t", sourceStoppedAt: "t", incrementalSnapshotName: "y", incrementalSentAt: "t", targetVmCreated: true };
  assert.equal(nextPhase(upToCreate, { dedicated: false }), "START_TARGET", "NAT skips MOVE_IP");
  assert.equal(nextPhase(upToCreate, { dedicated: true }), "MOVE_IP");
  assert.equal(nextPhase({ ...upToCreate, ipMovedAt: "t", targetVerified: true }, { dedicated: true }), "COMMIT");
  assert.equal(nextPhase({ ...upToCreate, targetVerified: true, committedAt: "t" }, { dedicated: false }), "DONE");
});

test("rollbackAllowed flips off at COMMIT", () => {
  assert.equal(rollbackAllowed({ sourceStoppedAt: "t" }), true);
  assert.equal(rollbackAllowed({ committedAt: "t" }), false);
});

test("rollbackSteps undoes exactly what exists, in the safe order", () => {
  assert.deepEqual(rollbackSteps({}, { dedicated: false }), ["RESTORE_DB_STATUS"]);
  assert.deepEqual(rollbackSteps({ fullSentAt: "t" }, { dedicated: false }), ["DESTROY_TARGET_DATASET", "RESTORE_DB_STATUS"]);
  assert.deepEqual(
    rollbackSteps({ fullSentAt: "t", sourceStoppedAt: "t", incrementalSnapshotName: "n", targetVmCreated: true, targetSnippetWritten: true, ipMovedAt: "t", targetStartedAt: "t" }, { dedicated: true }),
    ["MOVE_IP_BACK", "STOP_TARGET", "DESTROY_TARGET_VM", "DELETE_TARGET_SNIPPET", "DELETE_SOURCE_INCREMENTAL_SNAPSHOT", "START_SOURCE", "RESTORE_DB_STATUS"],
  );
  // A NAT move never moves an IP even if a stale flag were present.
  assert.ok(!rollbackSteps({ ipMovedAt: "t" }, { dedicated: false }).includes("MOVE_IP_BACK"));
});

